class MemoryManager:
    def __init__(self, block_size, total_blocks):
        self.block_size = block_size
        self.total_blocks = total_blocks
        self.bitmap = [False] * total_blocks

    def allocate(self, num_blocks):
        for i in range(self.total_blocks - num_blocks + 1):
            if all(not self.bitmap[i+j] for j in range(num_blocks)):
                for j in range(num_blocks):
                    self.bitmap[i+j] = True
                return i
        return -1

    def deallocate(self, start_block, num_blocks):
        for i in range(start_block, start_block + num_blocks):
            self.bitmap[i] = False

