import re

class Person:
    min_age = 0
    max_age = 120
    email_regex = re.compile(r"[^@]+@[^@]+\.[^@]+")

    def __init__(self, name, age, email):
        self.validate_data(name, age, email)
        self.name = name
        self.age = age
        self.email = email

    def validate_data(self, name, age, email):
        if not isinstance(name, str) or not name.isalpha():
            raise ValueError("Name should consist of letters only.")

        if not isinstance(age, int) or not self.min_age <= age <= self.max_age:
            raise ValueError(f"Age should be an integer between {self.min_age} and {self.max_age}.")

        if not Person.email_regex.match(email):
            raise ValueError("Invalid email format.")

    def __lt__(self, other):
        return self.age < other.age

    def __le__(self, other):
        return self.age <= other.age

    def __gt__(self, other):
        return self.age > other.age

    def __ge__(self, other):
        return self.age >= other.age

    def __eq__(self, other):
        return self.age == other.age

    def __ne__(self, other):
        return self.age != other.age
