```rust
// Custom enum representing different operations
enum Op {
    UnownedRegisterMove(Register, Register),
    UnownedStackAllocateMemory(u32),
}

// Custom type representing a register
#[derive(Clone)]
struct Register {
    // Implementation details not shown
