public class ReplaceVowels {

  public static String replaceVowels(String s) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (c == 'a' || c == 'A') {
        sb.append('a');
      } else if (c == 'e' || c == 'E') {
        sb.append('e');
      } else if (c == 'i' || c == 'I') {
        sb.append('i');
      } else if (c == 'o' || c == 'O') {
        sb.append('o');
      } else if (c == 'u' || c == 'U') {
        sb.append('u');
      } else {
        sb.append(c);
      }
    }
    return sb.toString();
  }

