public class LoggerManager
{
    private ObservableCollection<LoggerBase> _Loggers;

    public LoggerManager()
    {
        _Loggers = new ObservableCollection<LoggerBase>();
    }

    public ObservableCollection<LoggerBase> Loggers
    {
        get { return this._Loggers; }
    }

    public void RegisterLogger(LoggerBase logger)
    {
        _Loggers.Add(logger);
    }

    public void LogMessage(string message)
    {
        foreach (var logger in _Loggers)
        {
            logger.Log(message);
        }
    }
}
