const axios = require('axios');
const rateLimit = require('axios-rate-limit');
const sqlite3 = require('sqlite3').verbose();

// Function to handle rate limiting
const apiLimiter = rateLimit(axios.create(), { maxRequests: 10, perMilliseconds: 60000 });

// Create a local database for caching
const db = new sqlite3.Database(':memory:');

// Function to query the API for movie details
async function getMovieDetails(movieId, callback) {
  const cachedData = await checkCache(movieId);
  if (cachedData) {
    callback(null, cachedData);
  } else {
    try {
      const response = await apiLimiter.get(`https://api.themoviedb.org/3/movie/${movieId}?api_key=YOUR_API_KEY`);
      const movieData = {
        releaseDate: response.data.release_date,
        cast: response.data.credits.cast.map((actor) => actor.name),
      };
      cacheData(movieId, movieData);
      callback(null, movieData);
    } catch (error) {
      callback(error);
    }
  }
}

// Function to check if data is available in the cache
function checkCache(movieId) {
  return new Promise((resolve) => {
    db.get(`SELECT data FROM cache WHERE movieId = ?`, [movieId], (err, row) => {
      if (err) {
        resolve(null);
      } else {
        resolve(row ? JSON.parse(row.data) : null);
      }
    });
  });
}

// Function to cache the API response
function cacheData(movieId, movieData) {
  db.run(`INSERT OR REPLACE INTO cache (movieId, data) VALUES (?, ?)`, [movieId, JSON.stringify(movieData)]);
}

// Function to handle pagination and retrieve all movies directed by Christopher Nolan
async function getAllMovies(callback) {
  let page = 1;
  let totalPages = 1;
  const movies = [];

  while (page <= totalPages) {
    try {
      const response = await apiLimiter.get(`https://api.themoviedb.org/3/discover/movie?api_key=YOUR_API_KEY&with_crew=5255&sort_by=release_date.desc&page=${page}`);
      response.data.results.forEach((movie) => movies.push(movie));
      totalPages = response.data.total_pages;
      page++;
    } catch (error) {
      callback(error);
      return;
    }
  }

  callback(null, movies);
}

// Example usage
getAllMovies((error, movies) => {
  if (error) {
    console.error('Error:', error);
    return;
  }

  movies.forEach((movie) => {
    getMovieDetails(movie.id, (err, data) => {
      if (err) {
        console.error('Error:', err);
      } else {
        console.log(`Title: ${movie.title}`);
        console.log(`Release Date: ${data.releaseDate}`);
        console.log(`Cast: ${data.cast.join(', ')}`);
        console.log('---');
      }
    });
  });
});

// Close the database connection when done
process.on('exit', () => {
  db.close();
});
