import re
from datetime import date, timedelta

class User:
    def __init__(self, username, password, dob, email, phone_number):
        self.username = username
        self.password = password
        self.dob = dob
        self.email = email
        self.phone_number = phone_number

    def validate_password_complexity(self):
        if len(self.password) < 8:
            return False
        if not re.search(r'[A-Z]', self.password):
            return False
        if not re.search(r'[a-z]', self.password):
            return False
        if not re.search(r'\d', self.password):
            return False
        common_words = ['password', '12345678']
        for word in common_words:
            if word in self.password:
                return False
        return True

    def verify_email_format(self):
        if not re.match(r'^[\w\.\-]+@[\w]+\.[\w\.]+$', self.email):
            return False
        return True

    def calculate_age(self):
        today = date.today()
        age = today.year - self.dob.year
        if today.month < self.dob.month or (today.month == self.dob.month and today.day < self.dob.day):
            age -= 1
        return age

    def get_users_in_age_range(self, min_age, max_age):
        users_in_range = []
        for user in self.users:
            age = user.calculate_age()
            if age >= min_age and age <= max_age:
                users_in_range.append(user)
        return users_in_range

    def check_password_strength(self):
        score = 0
        score += len(self.password) * 4
        score += sum([1 for char in self.password if char.isupper()])
        score += sum([1 for char in self.password if char.islower()])
        score += sum([1 for char in self.password if char.isdigit()])
        common_words = ['password', '12345678']
        if any(word in self.password for word in common_words):
            score -= 20
        return min(100, max(0, score))
