public class HelloWorldConverter {

    public static String helloWorld(String input) {
        if (input == null) {
            return null;
        }

        if (input.isEmpty()) {
            return "";
        }

        StringBuilder result = new StringBuilder();
        char prevVowel = '\0';

        for (char c : input.toLowerCase().toCharArray()) {
            if (isVowel(c)) {
                if (prevVowel != '\0') {
                    continue;
                }
                c = getNextVowel(c);
                prevVowel = c;
            } else if (Character.isUpperCase(c)) {
                result.append(Character.toUpperCase(c));
                continue;
            }

            result.append(c);
            prevVowel = '\0';
        }

        return result.toString();
    }

    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    private static char getNextVowel(char c) {
        switch (c) {
            case 'a':
                return 'e';
            case 'e':
                return 'i';
            case 'i':
                return 'o';
            case 'o':
                return 'u';
            case 'u':
                return 'a';
            default:
                return c;
        }
    }
}
