            print("Failed to execute SQL query. Exception: ", e)
            return None

    def fill_missing(self, df, method='mean'):
        try:
            if method == 'mean':
                df.fillna(df.mean(), inplace=True)
            elif method == 'median':
                df.fillna(df.median(), inplace=True)
            elif method == 'mode':
                df.fillna(df.mode().iloc[0], inplace=True)
        except Exception as e:
            print("An error occurred while filling missing values Exception: ", e)


