            numeric_features = df.select_dtypes(include=['int64', 'float64']).columns
            for feature in numeric_features:
                mean, std = df[feature].mean(), df[feature].std()
                if std == 0:
                    print(f"Standard deviation for feature {feature} is zero, skipping normalization for this feature.")
                    continue
                df[feature] = (df[feature] - mean) / std
        except Exception as e:
            print("An error occurred while normalizing numeric data Exception: ", e)

    def preprocess(self, df, fill_method='mean'):
        try:
            self.fill_missing(df, method=fill_method)
            self.normalize_numeric(df)
