The Sieve of Eratosthenes is a much more efficient method to find prime numbers up to a given limit. It operates by iteratively marking the multiples of each prime number, starting from the first prime number, 2. The multiples of a given prime are generated as a sequence of numbers starting from that prime, with a constant difference between them equal to that prime. Here is an example:

```c
#include<stdio.h>
#include<math.h>

void SieveOfEratosthenes(int list[], int n, int size) {
  int maxVal = 0;
  for (int i = 0; i < size; i++) {
    if (list[i] > maxVal) {
      maxVal = list[i];
    }
  }
  int prime[maxVal+1];
  memset(prime, 1, sizeof(prime));

  for (int p = 2; p*p <= maxVal; p++) {
    if (prime[p] == 1) {
      for (int i = p*p; i <= maxVal; i += p)
        prime[i] = 0;
    }
  }

  int count = 0;
  for (int i = 0; i < size; i++) {
    if (prime[list[i]] == 1) {
      count++;
    }
  }

  printf("Number of prime numbers in the list: %d\n", count);
}

int main() {
    int list[] = {2, 3, 4, 5, 6, 7, 8, 9, 10};
    int n = sizeof(list)/sizeof(list[0]);
    SieveOfEratosthenes(list, n);

    return 0;
}
```

