class Node:
    def __init__(self, data=None):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def add(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

def add_lists(list1, list2):
    result = LinkedList()
    carry = 0
    current1 = list1.head
    current2 = list2.head

    while current1 or current2:
        if current1:
            digit1 = current1.data
            current1 = current1.next
        else:
            digit1 = 0
        if current2:
            digit2 = current2.data
            current2 = current2.next
        else:
            digit2 = 0

        digit_sum = digit1 + digit2 + carry
        carry = digit_sum // 10
        result.add(digit_sum % 10)

    if carry > 0:
        result.add(carry)

    return result

