// Define the HTTPClient protocol
protocol HTTPClient {
    func get(from url: URL, completion: @escaping (Result<Data, Error>) -> Void)
}

// Implement the FeedLoader class
class FeedLoader {
    let url: URL
    let client: HTTPClient

    init(url: URL, client: HTTPClient) {
        self.url = url
        self.client = client
    }

    func load(completion: @escaping (Result<Data, Error>) -> Void) {
        client.get(from: url) { result in
            completion(result)
        }
    }
}
