        string choice = Console.ReadLine();
        if (choice == "1")
        {
            Console.WriteLine("Pyramid volume: " + CalculatePyramidVolume(10, 10));
            Console.WriteLine("Frustum Pyramid volume: " + CalculateFrustumPyramidVolume(10, 10, 5, 5));
        }
        else if (choice == "2")
        {
            var pyramidVolumeTask = CalculatePyramidVolumeAsync(10, 10);
            var frustumPyramidVolumeTask = CalculateFrustumPyramidVolumeAsync(10, 10, 5, 5);
            Console.WriteLine("Pyramid volume: " + pyramidVolumeTask.Result);
            Console.WriteLine("Frustum Pyramid volume: " + frustumPyramidVolumeTask.Result);
        }
    }

    static double CalculatePyramidVolume(double baseArea, double height)
    {
        return (baseArea * height) / 3;
    }

    static Task<double> CalculatePyramidVolumeAsync(double baseArea, double height)
    {
        return Task.Run(() => CalculatePyramidVolume(baseArea, height));
    }

    static double CalculateFrustumPyramidVolume(double baseArea1, double height1, double baseArea2, double height2)
    {
        double vol1 = CalculatePyramidVolume(baseArea1, height1);
        double vol2 = CalculatePyramidVolume(baseArea2, height2);
        return vol1 - vol2;
    }

    static Task<double> CalculateFrustumPyramidVolumeAsync(double baseArea1, double height1, double baseArea2, double height2)
    {
        return Task.Run(() => CalculateFrustumPyramidVolume(baseArea1, height1, baseArea2, height2));
    }
}
