def roman_to_int(s: str) -> int:
    roman = {'I': 1, 
             'V': 5, 
             'X': 10, 
             'L': 50, 
             'C': 100, 
             'D': 500,
             'M': 1000}
    int_val = 0
    for i in range(len(s)):
        if i > 0 and roman[s[i]] > roman[s[i - 1]]:
            int_val += roman[s[i]] - 2 * roman[s[i - 1]]
        else:
