        if s.startswith('0x'):
            return float(int(s, 16))
        elif s.startswith('0b'):
            return float(int(s, 2))
        elif s.startswith('0o'):
            return float(int(s, 8))
        elif s.startswith('#'):
            return float(int(s[1:], 16))
