def kth_smallest_element(A, B, k):
    m, n = len(A), len(B)
    if m > n:
        A, B, m, n = B, A, n, m
    if k > m + n:
        return -1

    low, high = max(0, k - n), min(k, m)

    while low <= high:
        mid_A = (low + high) // 2
        mid_B = k - mid_A

        if mid_A < m and B[mid_B - 1] > A[mid_A]:
            low = mid_A + 1
        elif mid_A > 0 and A[mid_A - 1] > B[mid_B]:
            high = mid_A - 1
        else:
            if mid_A == 0:
                return B[mid_B - 1]
            elif mid_B == 0:
                return A[mid_A - 1]
            else:
                return max(A[mid_A - 1], B[mid_B - 1])

    return -1

