```python
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()

    def peek(self):
        if not self.is_empty():
            return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

def hanoi_iterative(n, source, target):
    moves = 0
    stacks = {'A': source, 'B': Stack(), 'C': target}

    if n % 2 == 0:
        auxiliary = 'C'
    else:
        auxiliary = 'B'

    for i in range(1, n+1):
        source.push(i)

    total_moves = 2**n - 1

    while moves < total_moves:
        if moves % 3 == 0:
            move_disk(stacks, source, auxiliary)
        elif moves % 3 == 1:
            move_disk(stacks, source, target)
        elif moves % 3 == 2:
            move_disk(stacks, auxiliary, target)

        moves += 1

    print("Minimum number of moves required:", total_moves)
    return total_moves

def move_disk(stacks, source, target):
    disk = source.pop()
    target.push(disk)
    print("Move disk", disk, "from stack", source, "to stack", target)

