function isPrime(num) {
  if (num <= 1) {
    return false;
  }
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false;
    }
  }
  return true;
}

function isTwinPrime(num) {
  if (isPrime(num)) {
    if (isPrime(num - 3) || isPrime(num + 3)) {
      return true;
    }
  }
  return false;
}

function isPerfectSquare(num) {
  return Math.sqrt(num) % 1 === 0;
}

function checkNumber(num) {
