import math

class GeometricShape:
    def __init__(self, color, height, weight, shape_type):
        self.color = color
        self.height = height
        self.weight = weight
        self.shape_type = shape_type

    def get_area(self):
        if self.shape_type == "square":
            if self.height <= 0:
                raise ValueError("Invalid height for a square.")
            return self.height ** 2
        elif self.shape_type == "rectangle":
            if self.height <= 0 or self.weight <= 0:
                raise ValueError("Invalid dimensions for a rectangle.")
            return self.height * self.weight
        elif self.shape_type == "circle":
            if self.weight <= 0:
                raise ValueError("Invalid radius for a circle.")
            return math.pi * (self.weight ** 2)
        elif self.shape_type == "triangle":
            if self.height <= 0 or self.weight <= 0:
                raise ValueError("Invalid dimensions for a triangle.")
            return (self.height * self.weight) / 2
        else:
            raise ValueError("Invalid shape type.")

    def get_perimeter(self):
        if self.shape_type == "square":
            if self.height <= 0:
                raise ValueError("Invalid height for a square.")
            return 4 * self.height
        elif self.shape_type == "rectangle":
            if self.height <= 0 or self.weight <= 0:
                raise ValueError("Invalid dimensions for a rectangle.")
            return 2 * (self.height + self.weight)
        elif self.shape_type == "circle":
            if self.weight <= 0:
                raise ValueError("Invalid radius for a circle.")
            return 2 * math.pi * self.weight
        elif self.shape_type == "triangle":
            if self.height <= 0 or self.weight <= 0:
                raise ValueError("Invalid dimensions for a triangle.")
            return self.height + self.weight + math.sqrt((self.height ** 2) + (self.weight ** 2))
        else:
            raise ValueError("Invalid shape type.")

    def display_info(self):
        try:
            area = self.get_area()
            perimeter = self.get_perimeter()
            print(f"Color: {self.color}")
            print(f"Height: {self.height}")
            print(f"Weight: {self.weight}")
            print(f"Shape Type: {self.shape_type}")
            print(f"Area: {area}")
            print(f"Perimeter: {perimeter}")
        except ValueError as e:
            print(f"Error: {str(e)}")

