```c
#include <stddef.h>

// Structure to represent a memory block
typedef struct block {
    size_t size;  // Size of the block
    struct block *next;  // Pointer to the next block
    int free;  // Flag to indicate if the block is free (1) or allocated (0)
} block;

// Pointer to the start of the memory block
void *start = NULL;

// Function to initialize the memory allocation system
void initialize_memory(void *start, size_t size) {
    block *initial_block = (block *)start;
    initial_block->size = size - sizeof(block);
    initial_block->next = NULL;
    initial_block->free = 1;
}

// Function to allocate memory
void *my_malloc(size_t size) {
    block *current = (block *)start;
    while (current) {
        if (current->free && current->size >= size) {
            if (current->size > size + sizeof(block)) {
                block *new_block = (block *)((char *)current + sizeof(block) + size);
                new_block->size = current->size - size - sizeof(block);
                new_block->next = current->next;
                new_block->free = 1;
                current->size = size;
                current->next = new_block;
            }
            current->free = 0;
            return (void *)(current + 1);
        }
        current = current->next;
    }
    return NULL;
}

// Function to free memory
void my_free(void *ptr) {
    if (ptr) {
        block *current = (block *)ptr - 1;
        current->free = 1;
        if (current->next && current->next->free) {
            current->size += sizeof(block) + current->next->size;
            current->next = current->next->next;
        }
        if (current->next && current->next->free) {
            my_free(current->next + 1);
        }
    }
}
