Here is an implementation of a recursive binary search algorithm that returns both the element and its index:

```python
def binary_search(arr, target, low, high):
    if low > high:
        return None, -1

    mid = (low + high) // 2

    if arr[mid] == target:
        index = find_first_occurrence(arr, target, low, mid)
        return arr[index], index
    elif arr[mid] > target:
        return binary_search(arr, target, low, mid - 1)
    else:
        return binary_search(arr, target, mid + 1, high)

def find_first_occurrence(arr, target, low, high):
    while low < high:
        mid = (low + high) // 2
        if arr[mid] == target:
            high = mid
        else:
            low = mid + 1
    return low

