def modular_inverse(a, m):
    def egcd(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            g, x, y = egcd(b % a, a)
            return (g, y - (b // a) * x, x)

    g, x, y = egcd(a, m)
    if g != 1:
        return None  # Modular inverse does not exist
    else:
        return x % m
```
