```swift
class MaxQueue {
    private var queue: [Int] = []
    private var maxQueue: [Int] = []

    func enqueue(_ element: Int) {
        queue.append(element)
        while let last = maxQueue.last, last < element {
            maxQueue.removeLast()
        }
        maxQueue.append(element)
    }

    func dequeue() -> Int? {
        guard let element = queue.first else { return nil }
        if element == maxQueue.first {
            maxQueue.removeFirst()
        }
        queue.removeFirst()
        return element
    }

    func max() -> Int? {
        return maxQueue.first
    }
}

