  constructor(number, string, objects, bool) {
    if (typeof number !== 'number' || isNaN(number)) {
      throw new Error('Invalid number argument');
    }
    if (typeof string !== 'string') {
      throw new Error('Invalid string argument');
    }
    if (!Array.isArray(objects) || objects.length === 0) {
      throw new Error('Invalid array of objects argument');
    }
    if (typeof bool !== 'boolean') {
      throw new Error('Invalid boolean argument');
    }

