```java
public class PrimeNotFoundException extends Exception {
    private int iterations;

    public PrimeNotFoundException(int iterations) {
        super("No prime number found within the first 10000 numbers");
        this.iterations = iterations;
    }

    public int getIterations() {
        return iterations;
    }
}

public class PrimeFinder {
    public static void main(String[] args) {
        int number = 1001;
        int iterations = 0;

        while (number <= 10000) {
            try {
                number = findNextPrime(number, iterations);
                System.out.println("First prime number greater than 1000: " + number);
                break;
            } catch (PrimeNotFoundException e) {
                iterations = e.getIterations();
                System.out.println(e.getMessage());
            }
        }
    }

    public static int findNextPrime(int start, int iterations) throws PrimeNotFoundException {
        boolean[] isPrime = new boolean[10001];
        for (int i = 2; i < isPrime.length; i++) {
            isPrime[i] = true;
        }

        int count = 0;
        int current = 2;
        while (count < iterations) {
            if (isPrime[current]) {
                count++;
                if (count == iterations) {
                    break;
                }
                for (int i = 2 * current; i < isPrime.length; i += current) {
                    isPrime[i] = false;
                }
            }
            current++;
        }

        for (int i = start; i < isPrime.length; i++) {
            if (isPrime[i]) {
                return i;
            }
        }

        throw new PrimeNotFoundException(iterations);
    }
}
