function findSecondLargest(arr) {
  if (arr.length < 2) {
    return "Error: Array should contain at least 2 elements.";
  }

  let max = arr[0];
  let secondMax = null;
  let duplicates = {};

  for (let i = 1; i < arr.length; i++) {
    if (arr[i] === max) {
      throw new Error("Error: Array contains duplicate numbers.");
    }
    if (arr[i] > max) {
      secondMax = max;
      max = arr[i];
    } else if (arr[i] > secondMax || secondMax === null) {
      secondMax = arr[i];
    }
  }

  if (secondMax === null) {
