```java
import java.util.Objects;

class PrimeNumberException extends Exception {
    public PrimeNumberException(String message) {
        super(message);
    }
}

class InvalidPointException extends Exception {
    public InvalidPointException(String message) {
        super(message);
    }
}

class Point<T extends Number> {
    private T x;
    private T y;

    public Point(T x, T y) throws PrimeNumberException, InvalidPointException {
        if (!isPrime(x.intValue()) || !isPrime(y.intValue())) {
            throw new PrimeNumberException("The x and y coordinates must be prime numbers.");
        }
        if (x.intValue() < -100 || x.intValue() > 100 || y.intValue() < -100 || y.intValue() > 100) {
            throw new InvalidPointException("The x and y coordinates must be between -100 and 100 (inclusive).");
        }
        this.x = x;
        this.y = y;
    }

    public double distanceX(Point<T> other) {
        return Math.abs(other.x.doubleValue() - this.x.doubleValue());
    }

    public double distance(Point<T> other) {
        double xDiff = other.x.doubleValue() - this.x.doubleValue();
        double yDiff = other.y.doubleValue() - this.y.doubleValue();
        return Math.sqrt(xDiff * xDiff + yDiff * yDiff);
    }

    public boolean withinRectangle(Point<T> topLeft, Point<T> bottomRight) {
        return this.x.doubleValue() >= topLeft.x.doubleValue() &&
                this.x.doubleValue() <= bottomRight.x.doubleValue() &&
                this.y.doubleValue() >= topLeft.y.doubleValue() &&
                this.y.doubleValue() <= bottomRight.y.doubleValue();
    }

    public double slope(Point<T> other) throws InvalidPointException {
        double xDiff = other.x.doubleValue() - this.x.doubleValue();
        if (xDiff == 0) {
            throw new InvalidPointException("Cannot calculate the slope when the difference in x-coordinates is 0.");
        }
        double yDiff = other.y.doubleValue() - this.y.doubleValue();
        return yDiff / xDiff;
    }

    private boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    // Override equals and hashCode methods
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Point<?> point = (Point<?>) o;
        return Objects.equals(x, point.x) &&
                Objects.equals(y, point.y);
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);
    }
}
```

