```java
import java.util.Scanner;

public class ScientificCalculator {
    private static Scanner scanner = new Scanner(System.in);
    private static double memoryValue = 0.0;

    public static void main(String[] args) {
        while (true) {
            System.out.println("Enter an equation or command: ");
            String input = scanner.nextLine();

            if (input.equalsIgnoreCase("quit")) {
                break;
            } else if (input.equalsIgnoreCase("memory")) {
                System.out.println("Memory value: " + memoryValue);
            } else if (input.startsWith("memory store")) {
                String[] parts = input.split(" ");
                memoryValue = Double.parseDouble(parts[2]);
                System.out.println("Memory value stored.");
            } else if (input.startsWith("memory recall")) {
                System.out.println("Memory value: " + memoryValue);
            } else {
                try {
                    double result = evaluate(input);
                    System.out.println("Result: " + result);
                } catch (Exception e) {
                    System.out.println("Invalid input. Please try again.");
                }
            }
        }
    }

    private static double evaluate(String equation) {
        equation = equation.replace("sin", "Math.sin")
                           .replace("cos", "Math.cos")
                           .replace("tan", "Math.tan")
                           .replace("sqrt", "Math.sqrt")
                           .replace("exp", "Math.exp")
                           .replace("log", "Math.log")
                           .replace("pi", "Math.PI");

        return (double) evaluateExpression(equation);
    }

    private static Object evaluateExpression(String expression) {
        try {
            return Double.parseDouble(expression);
        } catch (NumberFormatException e) {
            // Continue
        }

        if (expression.contains("+")) {
            String[] parts = expression.split("\\+");
            return (double) evaluateExpression(parts[0]) + (double) evaluateExpression(parts[1]);
        } else if (expression.contains("-")) {
            String[] parts = expression.split("-");
            return (double) evaluateExpression(parts[0]) - (double) evaluateExpression(parts[1]);
        } else if (expression.contains("*")) {
            String[] parts = expression.split("\\*");
            return (double) evaluateExpression(parts[0]) * (double) evaluateExpression(parts[1]);
        } else if (expression.contains("/")) {
            String[] parts = expression.split("/");
            return (double) evaluateExpression(parts[0]) / (double) evaluateExpression(parts[1]);
        } else {
            throw new NumberFormatException();
        }
    }
}
