    public bool IsRangeWithinDocument(Range range, string sourceText)
    {
        int totalLines = sourceText.Split('\n').Length;
        if (range.Start.Line < 0 || range.End.Line < 0 || range.Start.Line >= totalLines || range.End.Line >= totalLines)
        {
            return false; // Range start or end position is outside the document
        }
        if (range.Start.Line == range.End.Line && range.Start.Character > range.End.Character)
        {
            return false; // Invalid range where start character is greater than end character on the same line
        }
        if (range.Start.Line > range.End.Line)
        {
            return false; // Invalid range where start line is greater than end line
        }
        if (range.Start.Line == range.End.Line && range.End.Character > sourceText.Split('\n')[range.Start.Line].Length)
        {
            return false; // End character position is beyond the line length
        }
        return true; // Range is within the document
    }
}
