Here is an implementation of a self-balancing binary search tree in JavaScript that meets all the given requirements:

```javascript
class Node {
  constructor(key, value) {
    this.key = key;
    this.value = value;
    this.left = null;
    this.right = null;
    this.height = 1;
  }
}

class AVLTree {
  constructor() {
    this.root = null;
  }

  getHeight(node) {
    if (node === null) return 0;
    return node.height;
  }

  getBalanceFactor(node) {
    if (node === null) return 0;
    return this.getHeight(node.left) - this.getHeight(node.right);
  }

  updateHeight(node) {
    if (node === null) return;
    node.height = 1 + Math.max(this.getHeight(node.left), this.getHeight(node.right));
  }

  rotateLeft(z) {
    const y = z.right;
    const T2 = y.left;

    y.left = z;
    z.right = T2;

    this.updateHeight(z);
    this.updateHeight(y);

    return y;
  }

  rotateRight(z) {
    const y = z.left;
    const T3 = y.right;

    y.right = z;
    z.left = T3;

    this.updateHeight(z);
    this.updateHeight(y);

    return y;
  }

  insert(key, value) {
    this.root = this._insert(this.root, key, value);
  }

  _insert(node, key, value) {
    if (node === null) return new Node(key, value);

    if (key < node.key) {
      node.left = this._insert(node.left, key, value);
    } else if (key > node.key) {
      node.right = this._insert(node.right, key, value);
    } else {
      node.value = value;
      return node;
    }

    this.updateHeight(node);

    const balanceFactor = this.getBalanceFactor(node);

    if (balanceFactor > 1) {
      if (key < node.left.key) {
        return this.rotateRight(node);
      } else if (key > node.left.key) {
        node.left = this.rotateLeft(node.left);
        return this.rotateRight(node);
      }
    }

    if (balanceFactor < -1) {
      if (key > node.right.key) {
        return this.rotateLeft(node);
      } else if (key < node.right.key) {
        node.right = this.rotateRight(node.right);
        return this.rotateLeft(node);
      }
    }

    return node;
  }

  delete(key) {
    this.root = this._delete(this.root, key);
  }

  _delete(node, key) {
    if (node === null) return null;

    if (key < node.key) {
      node.left = this._delete(node.left, key);
    } else if (key > node.key) {
      node.right = this._delete(node.right, key);
    } else {
      if (node.left === null && node.right === null) {
        node = null;
      } else if (node.left === null) {
        node = node.right;
      } else if (node.right === null) {
        node = node.left;
      } else {
        const successor = this.getMinNode(node.right);
        node.key = successor.key;
        node.value = successor.value;
        node.right = this._delete(node.right, successor.key);
      }
    }

    if (node === null) return null;

    this.updateHeight(node);

    const balanceFactor = this.getBalanceFactor(node);

    if (balanceFactor > 1) {
      if (this.getBalanceFactor(node.left) >= 0) {
        return this.rotateRight(node);
      } else {
        node.left = this.rotateLeft(node.left);
        return this.rotateRight(node);
      }
    }

    if (balanceFactor < -1) {
      if (this.getBalanceFactor(node.right) <= 0) {
        return this.rotateLeft(node);
      } else {
        node.right = this.rotateRight(node.right);
        return this.rotateLeft(node);
      }
    }

    return node;
  }

  search(key) {
    return this._search(this.root, key);
  }

  _search(node, key) {
    if (node === null) return null;

    if (key === node.key) return node.value;

    if (key < node.key) {
      return this._search(node.left, key);
    } else {
      return this._search(node.right, key);
    }
  }

  findMin() {
    return this.getMinNode(this.root)?.key;
  }

  getMinNode(node) {
    if (node === null || node.left === null) return node;
    return this.getMinNode(node.left);
  }

  findMax() {
    return this.getMaxNode(this.root)?.key;
  }

  getMaxNode(node) {
    if (node === null || node.right === null) return node;
    return this.getMaxNode(node.right);
  }

  findSuccessor(key) {
    const node = this._searchNode(this.root, key);
    if (node === null) return null;

    if (node.right !== null) {
      return this.getMinNode(node.right)?.key;
    }

    let successor = null;
    let current = this.root;

    while (current !== null) {
      if (current.key > key) {
        successor = current;
        current = current.left;
      } else if (current.key < key) {
        current = current.right;
      } else {
        break;
      }
    }

    return successor?.key;
  }

  findPredecessor(key) {
    const node = this._searchNode(this.root, key);
    if (node === null) return null;

    if (node.left !== null) {
      return this.getMaxNode(node.left)?.key;
    }

    let predecessor = null;
    let current = this.root;

    while (current !== null) {
      if (current.key < key) {
        predecessor = current;
        current = current.right;
      } else if (current.key > key) {
        current = current.left;
      } else {
        break;
      }
    }

    return predecessor?.key;
  }

  updateValue(key, newValue) {
    const node = this._searchNode(this.root, key);
    if (node !== null) {
      node.value = newValue;
    }
  }

  _searchNode(node, key) {
    if (node === null || key === node.key) return node;

    if (key < node.key) {
      return this._searchNode(node.left, key);
    } else {
      return this._searchNode(node.right, key);
    }
  }

  *[Symbol.iterator]() {
    yield* this._inOrderTraversal(this.root);
  }

  *_inOrderTraversal(node) {
    if (node === null) return;

    yield* this._inOrderTraversal(node.left);
    yield node.key;
    yield* this._inOrderTraversal(node.right);
  }
}

