import numpy as np

def generate_dft_matrix(N: int) -> np.ndarray:
    D = np.zeros((N, N), dtype=np.complex128)
    for j in range(N):
        for k in range(N):
            D[j, k] = 1 / np.sqrt(N) * np.exp(-2j * np.pi * j * k / N)
    return D
