```jsx
import React, { useState } from 'react';

const PASSWORD_STRENGTH_THRESHOLD = 3; // minimum strength required
const MAX_ATTEMPTS = 3; // maximum number of incorrect attempts
const RESET_LINK_EXPIRATION = 300; // in seconds

const PasswordProtectedText = ({ text }) => {
  const [isLocked, setIsLocked] = useState(true);
  const [showText, setShowText] = useState(false);
  const [password, setPassword] = useState('');
  const [attempts, setAttempts] = useState(0);
  const [strength, setStrength] = useState(0);
  const [showModal, setShowModal] = useState(false);
  const [email, setEmail] = useState('');
  const [resetLinkExpiration, setResetLinkExpiration] = useState(RESET_LINK_EXPIRATION);

  const handlePasswordChange = (e) => {
    const newPassword = e.target.value;
    setPassword(newPassword);
    setStrength(calculatePasswordStrength(newPassword));
  };

  const handlePasswordSubmit = (e) => {
    e.preventDefault();

    if (password === 'password123') {
      setIsLocked(!isLocked);
      setShowText(!showText);
      setPassword('');
      setAttempts(0);
    } else {
      setAttempts(attempts + 1);
    }
  };

  const handleForgotPassword = (e) => {
    e.preventDefault();
    setShowModal(true);
  };

  const handleEmailSubmit = (e) => {
    e.preventDefault();
    // Code to send password reset email
    setShowModal(false);
    setResetLinkExpiration(RESET_LINK_EXPIRATION);
  };

  const calculatePasswordStrength = (password) => {
    let strength = 0;

    // Evaluate password strength criteria
    const criteria = {
      length: password.length >= 8,
      uppercase: /[A-Z]/.test(password),
      lowercase: /[a-z]/.test(password),
      number: /[0-9]/.test(password),
      specialChar: /[!@#$%^&*]/.test(password),
    };

    Object.values(criteria).forEach((criterion) => {
      if (criterion) {
        strength++;
      }
    });

    return strength;
  };

  return (
    <div>
      {isLocked && (
        <>
          <button onClick={handleForgotPassword}>Forgot Password</button>
          <form onSubmit={handlePasswordSubmit}>
            <input
              type="password"
              placeholder="Enter Password"
              value={password}
              onChange={handlePasswordChange}
            />
            <button type="submit">Unlock</button>
          </form>
          {attempts > 0 && (
            <p>Incorrect password. Attempts remaining: {MAX_ATTEMPTS - attempts}</p>
          )}
        </>
      )}
      {!isLocked && showText && <p>{text}</p>}
      {!isLocked && (
        <div>
          <p>Password Strength: {strength} / {PASSWORD_STRENGTH_THRESHOLD}</p>
          <progress value={strength} max={PASSWORD_STRENGTH_THRESHOLD}></progress>
        </div>
      )}
      {showModal && (
        <div>
          <form onSubmit={handleEmailSubmit}>
            <input
              type="email"
              placeholder="Enter your email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
            <button type="submit">Submit</button>
          </form>
          <p>Reset link expires in: {resetLinkExpiration} seconds</p>
        </div>
      )}
    </div>
  );
};

export default PasswordProtectedText;
```

In this example, the `PasswordProtectedText` component maintains its state using React hooks. It keeps track of the `isLocked` state to determine whether the text should be displayed. The `showText` state toggles the visibility of the text. The `password` state stores the value entered by the user in the password input field. The `attempts` state keeps track of the number of incorrect password attempts. The `strength` state tracks the strength of the entered password based on the predefined criteria. The `showModal` state controls the visibility of the password reset modal. The `email` state stores the email entered by the user. The `resetLinkExpiration` state keeps track of the remaining time before the password reset link expires.

The component includes event handlers such as `handlePasswordChange`, `handlePasswordSubmit`, `handleForgotPassword`, and `handleEmailSubmit` to handle user interactions. The `calculatePasswordStrength` function evaluates the strength of the entered password based on predefined criteria and returns a strength value between 0 and `PASSWORD_STRENGTH_THRESHOLD`.

The component renders different elements based on the current state. It displays the password input and unlock button when the component is locked, and the text when it is unlocked and `showText` is true. It also shows feedback on the number of incorrect attempts, password strength, and a progress bar indicating the strength level. The "Forgot Password" link triggers the display of the password reset modal, which prompts the user to enter their email. After submitting the email, a reset link expiration timer is displayed.

