class SortedStack:
    def __init__(self):
        self.contents = []
        self._sorted = False

    def push(self, value):
        self.contents.append(value)
        self._sorted = False

    def pop(self):
        if not self._sorted:
            self.sort()
        return self.contents.pop()

    def peek(self, index=None):
        if not self._sorted:
            self.sort()
        if index is None:
            index = len(self.contents) - 1
        return self.contents[index]

    def sort(self):
        self.contents.sort()
        self._sorted = True
```

