                        if (trimmedLine.indexOf("*/") + 2 < trimmedLine.length()) {
                            count++;
                        }
                    }
                } else {
                    if (trimmedLine.startsWith("/*") && trimmedLine.endsWith("*/")) {
                        count++;
                    } else if (trimmedLine.startsWith("/*")) {
                        inBlockComment = true;
                    } else {
                        count++;
                    }
                }
            }
        }
        return count;
    }
}
