```typescript
type Feature = {
  feature: {
    groupType: string;
    // other properties...
  }
  // other properties...
}

type FeatureGroup = {
  groupType: string;
  features: Feature[];
}

type ProcessedData = {
  groups: FeatureGroup[];
  groupMap: Map<string, number>;
  features: Feature[];
}

function processFeatures(json: Feature[]): ProcessedData {
  const groups: FeatureGroup[] = [];
  const groupMap = new Map<string, number>();

  json.forEach(feature => {
    const groupType = feature.feature.groupType;
    if (!groupMap.has(groupType)) {
      const group: FeatureGroup = { groupType, features: [feature] };
      groups.push(group);
      groupMap.set(groupType, groups.length - 1);
    } else {
      const groupIndex = groupMap.get(groupType)!;
      groups[groupIndex].features.push(feature);
    }
  });

  return { groups, groupMap, features: json };
}
