```javascript
function isValidColorCode(colorCode) {
  // Check if the string starts with "#" and has a length of 7 (including the "#")
  if (colorCode[0] !== "#" || colorCode.length !== 7) {
    return false;
  }

  // Check if all characters after the "#" are either digits or letters
  for (let i = 1; i < colorCode.length; i++) {
    const charCode = colorCode.charCodeAt(i);
    if (
      !(charCode >= 48 && charCode <= 57) && // Digit (0-9)
      !(charCode >= 65 && charCode <= 70) && // Uppercase letter (A-F)
      !(charCode >= 97 && charCode <= 102) // Lowercase letter (a-f)
    ) {
      return false;
    }
  }

  // Check if the color code represents a valid RGBA color
  const red = parseInt(colorCode.substring(1, 3), 16);
  const green = parseInt(colorCode.substring(3, 5), 16);
  const blue = parseInt(colorCode.substring(5, 7), 16);
  const alpha = parseInt(colorCode.substring(7, 9), 16);

  return (
    red >= 0 && red <= 255 &&
    green >= 0 && green <= 255 &&
    blue >= 0 && blue <= 255 &&
    alpha >= 0 && alpha <= 255
  );
}
```

