Here's a JavaScript code that randomly generates a 2D array and ensures that the sum of all positive elements is greater than or equal to 500. It also keeps track of the maximum and minimum values in the array and prints them at the end:

```javascript
function generateRandomArray(m, n) {
  // Initialize variables
  let array = [];
  let sum = 0;
  let max = -Infinity;
  let min = Infinity;

  // Generate random array
  for (let i = 0; i < m; i++) {
    array[i] = [];
    for (let j = 0; j < n; j++) {
      // Generate random value between -100 and 100
      let value = Math.floor(Math.random() * 201) - 100;
      array[i][j] = value;

      // Update sum, max, and min
      if (value > 0) {
        sum += value;
      }
      if (value > max) {
        max = value;
      }
      if (value < min) {
        min = value;
      }
    }
  }

  // Check if sum of positive elements is less than 500
  if (sum < 500) {
    return generateRandomArray(m, n);
  }

  // Print array, sum, max, and min
  console.log("Generated Array:", array);
  console.log("Sum of Positive Elements:", sum);
  console.log("Max Value:", max);
  console.log("Min Value:", min);
}

// Example usage: generateRandomArray(3, 4);
```

