import Foundation

func extractSeriesInfo(from json: Data) -> [MarvelDataModel.SeriesSummary] {
    struct ResponseData: Decodable {
        struct Series: Decodable {
            let resourceURI: String
            let title: String
        }
        let data: DataContainer
    }

    struct DataContainer: Decodable {
        let results: [ResponseData.Series]
    }

    do {
        let decoder = JSONDecoder()
        let responseData = try decoder.decode(ResponseData.self, from: json)
        return responseData.data.results.map { MarvelDataModel.SeriesSummary(resourceURI: $0.resourceURI, name: $0.title) }
    } catch {
        print("Error decoding JSON: \(error)")
        return []
    }
}

