Here is an example of a C++ program that counts the number of occurrences of each alphabetic character in a string without using any built-in functions or libraries:

```cpp
#include <iostream>

struct CharacterCount {
    char character;
    int count;
};

void countCharacters(const std::string& str, CharacterCount* charCounts, int& charCountsSize) {
    for (char c : str) {
        if (std::isalpha(c)) {
            // Convert the character to lowercase
            char lowercaseChar = std::tolower(c);

            // Find the character in the existing array of CharacterCount
            bool found = false;
            for (int i = 0; i < charCountsSize; i++) {
                if (charCounts[i].character == lowercaseChar) {
                    charCounts[i].count++;
                    found = true;
                    break;
                }
            }

            // If the character is not found, add it to the array
            if (!found) {
                charCounts[charCountsSize].character = lowercaseChar;
                charCounts[charCountsSize].count = 1;
                charCountsSize++;
            }
        }
    }
}

void sortCharacterCounts(CharacterCount* charCounts, int charCountsSize) {
    // Bubble sort the array of CharacterCount in descending order of count
    for (int i = 0; i < charCountsSize - 1; i++) {
        for (int j = 0; j < charCountsSize - i - 1; j++) {
            if (charCounts[j].count < charCounts[j + 1].count) {
                CharacterCount temp = charCounts[j];
                charCounts[j] = charCounts[j + 1];
                charCounts[j + 1] = temp;
            }
        }
    }
}

void printCharacterCounts(const CharacterCount* charCounts, int charCountsSize) {
    for (int i = 0; i < charCountsSize; i++) {
        std::cout << charCounts[i].character << " - " << charCounts[i].count << std::endl;
    }
}

int main() {
    std::string str = "Hello, World!";
    CharacterCount charCounts[26]; // Assuming only lowercase and uppercase English alphabets
    int charCountsSize = 0;

    countCharacters(str, charCounts, charCountsSize);
    sortCharacterCounts(charCounts, charCountsSize);
    printCharacterCounts(charCounts, charCountsSize);

    return 0;
}
```

This program takes a string as input (`str`) and counts the number of occurrences of each alphabetic character in the string. It uses an array of `CharacterCount` structures to store the character and its respective count. The `countCharacters` function iterates over each character in the string, converts it to lowercase, and updates the count accordingly. If a character is not found in the existing array, it is added to the array. The `sortCharacterCounts` function uses the bubble sort algorithm to sort the array in descending order of count. Finally, the `printCharacterCounts` function prints the characters along with their respective counts.

