```javascript
function calculatePolygonArea(n, sideLength, radius) {
  // Validate input parameters
  if (n < 3) {
    throw new Error("Number of sides must be at least 3.");
  }

  if (sideLength <= 0) {
    throw new Error("Side length must be greater than 0.");
  }

  // Calculate area of regular polygon
  if (n === 3) {
    return ((sideLength * sideLength * Math.sqrt(3)) / 4).toFixed(2);
  } else if (n === 4) {
    return (sideLength * sideLength).toFixed(2);
  }

  // Calculate area of polygon using complex formula
  const apothem = radius * Math.cos(Math.PI / n);
  const triangleSideLength = (2 * radius * Math.sin(Math.PI / n)).toFixed(2);
  const triangleArea = (0.5 * triangleSideLength * apothem).toFixed(2);

  return (n * triangleArea).toFixed(2);
}
```

