using namespace std;

// Function to calculate the Fibonacci series using recursion
int fibonacciRecursion(int n) {
    if (n <= 1)
        return n;
    return fibonacciRecursion(n - 1) + fibonacciRecursion(n - 2);
}

// Function to calculate the Fibonacci series using memoization
int fibonacciMemoization(int n, vector<int>& memo) {
    if (n <= 1)
        return n;
    if (memo[n] != -1)
        return memo[n];
    memo[n] = fibonacciMemoization(n - 1, memo) + fibonacciMemoization(n - 2, memo);
    return memo[n];
}

// Function to calculate the Fibonacci series using dynamic programming
int fibonacciDynamicProgramming(int n) {
    if (n <= 1)
        return n;
    int a = 0, b = 1, c;
    for (int i = 2; i <= n; i++) {
        c = a + b;
        a = b;
        b = c;
    }
    return b;
}

// Function to print the Fibonacci series up to the nth term
void printFibonacciSeries(int n) {
    if (n < 0)
        throw runtime_error("Invalid input: n cannot be negative");
    if (n == 0)
        return;
    vector<int> memo(n + 1, -1);

    cout << "Fibonacci series using recursion: ";
    for (int i = 0; i <= n; i++) {
        cout << fibonacciRecursion(i) << " ";
    }
    cout << endl;

    cout << "Fibonacci series using memoization: ";
    for (int i = 0; i <= n; i++) {
        cout << fibonacciMemoization(i, memo) << " ";
    }
    cout << endl;

    cout << "Fibonacci series using dynamic programming: ";
    for (int i = 0; i <= n; i++) {
        cout << fibonacciDynamicProgramming(i) << " ";
    }
    cout << endl;
}

int main() {
    int n;
    cout << "Enter the value of n: ";
    cin >> n;

    try {
        printFibonacciSeries(n);
    } catch (exception& e) {
        cout << "Exception: " << e.what() << endl;
    }

    return 0;
}

