use std::collections::BinaryHeap;
use std::cmp::Ordering;

#[derive(Debug, PartialEq, Eq)]
enum Message {
    RequestVoteCall(String),
    RequestVoteReply(String),
    AppendEntriesCall(String),
    AppendEntriesReply(String),
    InstallSnapshotCast(String),
}

#[derive(Debug, Default)]
struct Options {
    force_wakeup: bool,
}

#[derive(Debug, PartialEq, Eq)]
struct PrioritizedMessage {
    message: Message,
    priority: i32,
}

impl PartialOrd for PrioritizedMessage {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.priority.cmp(&other.priority))
    }
}

impl Ord for PrioritizedMessage {
    fn cmp(&self, other: &Self) -> Ordering {
        self.priority.cmp(&other.priority)
    }
}

struct MessageQueue {
    max_queue_len: Option<usize>,
    queue: BinaryHeap<PrioritizedMessage>,
}

impl MessageQueue {
    fn new(max_queue_len: Option<usize>) -> Self {
        MessageQueue {
            max_queue_len,
            queue: BinaryHeap::new(),
        }
    }

    fn enqueue(&mut self, message: Message, priority: i32) {
        if let Some(max_len) = self.max_queue_len {
            while self.queue.len() >= max_len {
                self.queue.pop();
            }
        }
        self.queue.push(PrioritizedMessage { message, priority });
    }

    fn dequeue(&mut self) -> Option<Message> {
        self.queue.pop().map(|pm| pm.message)
    }

    fn peek(&self) -> Option<&Message> {
        self.queue.peek().map(|pm| &pm.message)
    }
}

