def multiply_list(numbers):
    try:
        if not numbers:
            raise ValueError("Empty list")
        product = 1
        for num in numbers:
            if not isinstance(num, int) or num > 100 or num < 0:
                raise ValueError("Invalid number in the list")
            product *= num
        return product
    except ValueError as error:
        print(error)

