func toHex(_ num: Int) -> String {
    if num == 0 {
        return "0"
    }

    let hexChars: [Character] = Array("0123456789abcdef")
    var result = ""
    var n = num

    while n != 0 {
        let digit = n & 15
        result = String(hexChars[digit]) + result
        n >>= 4
    }

    return result
}
