def fibonacci_sequence(n: int) -> int:
    if n <= 0:
        raise ValueError("Input should be a positive integer")

    if n == 1 or n == 2:
        return 1

    prev, curr = 1, 1
    for _ in range(2, n):
        prev, curr = curr, prev + curr

    return curr
```

