    public AccessControlManager() {
        userRoles = new HashMap<>();
        roleAccess = new HashMap<>();
    }

    public void assignRole(String user, String role) {
        userRoles.computeIfAbsent(user, k -> new HashSet<>()).add(role);
    }

    public void grantAccess(String role, String resource) {
        roleAccess.computeIfAbsent(role, k -> new HashSet<>()).add(resource);
    }

    public void denyAccess(String role, String resource) {
        roleAccess.computeIfAbsent(role, k -> new HashSet<>()).remove(resource);
    }

    public boolean checkAccess(String user, String resource) {
        Set<String> userAssignedRoles = userRoles.getOrDefault(user, Collections.emptySet());
        for (String role : userAssignedRoles) {
            Set<String> roleResources = roleAccess.getOrDefault(role, Collections.emptySet());
            if (roleResources.contains(resource)) {
                return true;
            }
        }
        return false;
    }
}
