class Node: 
    # Node class to represent a node in the AVL tree
    def __init__(self, value=None):
        self.value = value
        self.left = None
        self.right = None
        self.height = 1


class AVLTree:
    # Class to represent an AVL tree
    def __init__(self):
        self.root = None

    def insert(self, root, value):
        """
        Function to perform the insertion
        """
        if not root:
            return Node(value)
        elif value < root.value:
            root.left = self.insert(root.left, value)
        else:
            root.right = self.insert(root.right, value)

        # Update the height of the ancestor node
        root.height = 1 + max(self.getHeight(root.left), self.getHeight(root.right))

        # Check whether this node became unbalanced or not
        balance = self.getBalance(root)

        # If the node is unbalanced, then there are 4 cases to consider

        # Case 1 - Left Left
        if balance > 1 and value < root.left.value:
            return self.rightRotate(root)

        # Case 2 - Right Right
        if balance < -1 and value > root.right.value:
            return self.leftRotate(root)

        # Case 3 - Left Right
        if balance > 1 and value > root.left.value:
            root.left = self.leftRotate(root.left)
            return self.rightRotate(root)

        # Case 4 - Right Left
        if balance < -1 and value < root.right.value:
            root.right = self.rightRotate(root.right)
            return self.leftRotate(root)

        return root

    def leftRotate(self, z):
        """
        Left rotate the node
        """
        y = z.right
        T2 = y.left
        y.left = z
        z.right = T2
        z.height = 1 + max(self.getHeight(z.left), self.getHeight(z.right))
        y.height = 1 + max(self.getHeight(y.left), self.getHeight(y.right))
        return y

    def rightRotate(self, y):
        """
        Right rotate the node
        """
        x = y.left
        T3 = x.right
        x.right = y
        y.left = T3
        y.height = 1 + max(self.getHeight(y.left), self.getHeight(y.right))
        x.height = 1 + max(self.getHeight(x.left), self.getHeight(x.right))
        return x

    def getHeight(self, root):
        """
        Get the height of the node
        """
        if not root:
            return 0
        return root.height

    def getBalance(self, root):
        """
        Calculate and get balance factor of the node
        """
        if not root:
            return 0
        return self.getHeight(root.left) - self.getHeight(root.right)

    def get_kth_smallest(self, root, k):
        """
        Function to get kth smallest element in AVL tree
        """
        if root is None:
            return None

        # Get the size of the left subtree
        left_size = self.getSize(root.left)

        # Check if kth smallest is root
        if k == left_size + 1:
            return root.value

        # Else if kth smallest is in left subtree
        elif k <= left_size:
            return self.get_kth_smallest(root.left, k)

        # Else if kth smallest is in right subtree
        else:
            return self.get_kth_smallest(root.right, k - left_size - 1)

    def getSize(self, root):
        """
        Function to get the size of the tree rooted at given node
        """
        if root is None:
            return 0
        return self.getSize(root.left) + 1 + self.getSize(root.right)


