struct CodingKeyMapping {
    private var keys: Set<String> = []

    mutating func addKey(key: String) {
        keys.insert(key)
    }

    mutating func removeKey(key: String) {
        keys.remove(key)
    }

    func encode(data: [String: Any]) -> [String: Any] {
        var encodedData: [String: Any] = [:]
        for (key, value) in data {
            if keys.contains(key) {
                if let codingKey = CodingKeys(rawValue: key) {
                    encodedData[codingKey.rawValue] = value
                }
            }
