use rand::Rng;

fn is_prime(n: u32) -> bool {
    if n < 2 {
        return false;
    }
    for i in 2..=n / 2 {
        if n % i == 0 {
            return false;
        }
    }
    true
}

fn is_palindrome(n: u32) -> bool {
    let mut number = n;
    let mut reverse = 0;
    while number > 0 {
        reverse = reverse * 10 + number % 10;
        number /= 10;
    }
    n == reverse
}

fn generate_palindrome_prime(min: u32, max: u32) -> Option<u32> {
    let mut rng = rand::thread_rng();
    let mut number = rng.gen_range(min, max + 1);
    while !is_prime(number) || !is_palindrome(number) {
        number = rng.gen_range(min, max + 1);
    }
    Some(number)
}

fn main() {
