    let max = 1000;
    let palindrome_prime = generate_palindrome_prime(min, max);
    match palindrome_prime {
        Some(number) => println!("Generated Palindrome Prime: {}", number),
        None => println!("No Palindrome Prime found within the range!"),
    }
}
