        double totalWeightedGrade = 0.0;
        double totalWeight = 0.0;
        for (Subject subject : enrolledSubjects) {
            double weight = calculateWeight(subject.getGrade());
            totalWeightedGrade += subject.getGrade() * weight;
            totalWeight += weight;
        }
        if (totalWeight == 0.0) {
            return 0.0;
        }
        return totalWeightedGrade / totalWeight;
    }

    private double calculateWeight(double grade) {
        double weightFactor = 1.0; // Default weight factor
        if (overallAverageGrade != 0.0) {
            weightFactor = 1.0 + ((grade - overallAverageGrade) / overallAverageGrade);
        }
        return weightFactor;
    }
}

