```python
def E(N):
    lines = set()
    for a in range(N+1):
        for b in range(N+1):
            for c in range(N+1):
                for d in range(N+1):
                    if (a, b, c, d) != (0, 0, 0, 0):
                        line = createLine((0, 0, 0, 0), (a, b, c, d))
                        lines.add(line)
