func fetchEntity(entityName: String) -> [[String: Any]] {
    let managedContext = persistentContainer.viewContext
    let fetchRequest = NSFetchRequest<NSFetchRequestResult>(entityName: entityName)

    do {
        let fetchedEntities = try managedContext.fetch(fetchRequest) as! [NSManagedObject]
        var result: [[String: Any]] = []

        for entity in fetchedEntities {
            var entityAttributes: [String: Any] = [:]
            for (key, value) in entity.entity.attributesByName {
                entityAttributes[key] = entity.value(forKey: key)
            }
            result.append(entityAttributes)
        }

        return result
    } catch {
        print("Failed to fetch \(entityName): \(error)")
        return []
    }
}
