def process_data(data):
    # 1. Filter out objects with prime age and count the number of 1s in binary
    filtered_data = []
    for obj in data:
        if not is_prime(obj['age']):
            filtered_data.append(obj)
        else:
            ones_count = count_ones_in_binary(obj['age'])
            if ones_count > 2:
                obj['age'] = ones_count
                filtered_data.append(obj)

    # 2. Sort the remaining objects based on name length and ASCII sum
    filtered_data.sort(key=lambda obj: (-len(obj['name']), -sum(ord(c) for c in obj['name'])))

    # 3. Group the objects based on the last letter of the name
    groups = defaultdict(list)
    for obj in filtered_data:
        last_letter = obj['name'][-1].lower()
        if last_letter in 'aeiou':
            groups['vowels'].append(obj)
        else:
            groups['consonants'].append(obj)

    # 4. Find the highest age divisible by 3 for each group and remove other objects
    for group in groups.values():
        max_age = 0
        max_age_email = ''
        for obj in group:
            if obj['age'] % 3 == 0 and obj['age'] > max_age:
                max_age = obj['age']
                max_age_email = obj['email']
        group[:] = [obj for obj in group if obj['age'] == max_age or obj['email'] == max_age_email]

    # 5. Calculate the median age of the remaining objects
    ages = [obj['age'] for group in groups.values() for obj in group]
    return int(median(ages))

