```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        long sum = 0;

        for (int i = 2; i <= 1000000; i++)
        {
            if (IsPrime(i))
            {
                sum += i;
            }
        }

        Console.WriteLine($"The sum of all prime numbers between 1 and 1,000,000 is: {sum}");
    }

    static bool IsPrime(int number)
    {
        if (number < 2)
        {
            return false;
        }

        for (int i = 2; i <= Math.Sqrt(number); i++)
        {
            if (number % i == 0)
            {
                return false;
            }
        }

        return true;
    }
}
```

