use embedded_hal::digital::v2::OutputPin;
use lpc8xx_hal::{Delay, Peripherals, CorePeripherals, SYSCON};

fn main() {
    let p = Peripherals::take().unwrap();
    let cp = CorePeripherals::take().unwrap();
    let mut syscon = p.SYSCON.split();

    let mut delay = Delay::new(p.TMRSE1, &mut syscon);

    let mut red = p.GPIO.enable.split(&mut syscon.handle);
    let mut yellow = p.GPIO.enable.split(&mut syscon.handle);
    let mut green = p.GPIO.enable.split(&mut syscon.handle);

    let mut red_light = red.pio0_0.into_output();
    let mut yellow_light = yellow.pio0_1.into_output();
    let mut green_light = green.pio0_2.into_output();

    loop {
        // Red light
        red_light.set_high().ok();
        delay.delay_ms(5000); // Red light duration

        // Yellow light
        red_light.set_low().ok();
        yellow_light.set_high().ok();
        delay.delay_ms(3000); // Yellow light duration

        // Green light
        yellow_light.set_low().ok();
        green_light.set_high().ok();
        delay.delay_ms(5000); // Green light duration
    }
}
