def extract_module_scope(file_path: str) -> str:
    with open(file_path, 'r') as file:
        for line in file:
            if '@@protoc_insertion_point(module_scope)' in line:
                return line.split('@@protoc_insertion_point(module_scope)')[1].strip(' \t\n\r')
    return ''  # Return empty string if the directive is not found
