function create2DArray(rowCount, colCount) {
    let arr = [];
    let tempArr = [];

    // Put numbers from 1 to rowCount*colCount into tempArray
    for(let i=1; i<=rowCount*colCount; i++) {
        tempArr.push(i);
    }

    // Shuffle tempArr to ensure randomness before taking elements to 2D array
    tempArr.sort(() => Math.random() - 0.5);

    for (let i = 0; i < rowCount; i++) {
        let tempRow = [];
        for (let j = 0; j < colCount; j++) {
            // Pick an element from tempArr and remove it
            let randomNumber = tempArr.splice(Math.floor(Math.random()*tempArr.length), 1)[0];
            tempRow.push(randomNumber);
        }
        // Sort each row in ascending order
        tempRow.sort((a, b) => a - b);
        arr.push(tempRow);
    }
    return arr;
}

