```java
class Node {
    int data;
    Node previous;
    Node next;

    public Node(int data) {
        this.data = data;
    }
}

class DoublyLinkedList {
    Node head;

    // Method to insert a node at the beginning of the doubly linked list
    public void insert(int data) {
        Node newNode = new Node(data);
        newNode.next = head;
        if (head != null) {
            head.previous = newNode;
        }
        head = newNode;
    }

    // Method to delete a node from the doubly linked list
    public void delete(int data) {
        Node currentNode = head;
        while (currentNode != null) {
            if (currentNode.data == data) {
                if (currentNode.previous != null) {
                    currentNode.previous.next = currentNode.next;
                } else {
                    head = currentNode.next;
                }
                if (currentNode.next != null) {
                    currentNode.next.previous = currentNode.previous;
                }
                break;
            }
            currentNode = currentNode.next;
        }
    }

    // Method to display the elements of the doubly linked list
    public void display() {
        Node currentNode = head;
        while (currentNode != null) {
            System.out.print(currentNode.data + " ");
            currentNode = currentNode.next;
        }
        System.out.println();
    }

    // Method to reverse the doubly linked list
    public void reverse() {
