    static void KMPSearch(string pat, string txt) {
        int M = pat.Length;
        int N = txt.Length;

        int[] lps = new int[M];
        int j = 0;

        computeLPSArray(pat, M, lps);

        int i = 0;
        int res = 0;
        int next_i = 0;

        while (i < N) {
            if (pat[j].ToString().ToLower() == txt[i].ToString().ToLower()) {
                j++;
                i++;
