    }

    // Case-sensitive KMP search
    static int CaseSensitiveKMPSearch(string pat, string txt) {
        return KMPSearch(pat, txt);
    }

    // KMP search algorithm
    static int KMPSearch(string pat, string txt) {
        int M = pat.Length;
        int N = txt.Length;

        // lps will hold the longest prefix suffix values for pattern
        int[] lps = new int[M];
        int j = 0;

        // Preprocess the pattern (calculate lps[] array)
        ComputeLPSArray(pat, M, lps);

        int i = 0; // index for txt[]
        int res = 0; // To store the result

        while (i < N) {
            if (pat[j] == txt[i]) {
                j++;
                i++;
            }
            if (j == M) {
                // When we find pattern
                res++;
                j = lps[j - 1];
            }
            // Mismatch after j matches
            else if (i < N && pat[j] != txt[i]) {
                if (j != 0)
                    j = lps[j - 1];
                else
                    i = i + 1;
            }
        }
        return res;
    }

    // Computes the longest prefix-suffix array.
    static void ComputeLPSArray(string pat, int M, int[] lps) {
        // Length of the previous longest prefix suffix
        int len = 0;
        int i = 1;
        lps[0] = 0; // lps[0] is always 0

        // The loop calculates lps[i] for i = 1 to M-1
        while (i < M) {
            if (pat[i] == pat[len]) {
                len++;
                lps[i] = len;
                i++;
            }
            else {
                if (len != 0) {
                    len = lps[len - 1];
                }
                else {
                    lps[i] = 0;
                    i++;
                }
            }
        }
