import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

public class InputValidator {
    public static String validateInputs(String[] inputs, double minValue, double maxValue, int decimalPlaces) {
        List<String> invalidInputs = new ArrayList<>();

        for (String input : inputs) {
            if (!isValidNumber(input)) {
                invalidInputs.add(input);
                continue;
            }

            double number = Double.parseDouble(input);

            if (number < minValue || number > maxValue) {
                invalidInputs.add(input);
                continue;
            }

            double roundedNumber = roundNumber(number, decimalPlaces);

            if (roundedNumber != number) {
                invalidInputs.add(input);
            }
        }

        if (invalidInputs.isEmpty()) {
            return "";
        } else {
            return String.join(", ", invalidInputs);
        }
    }

    private static boolean isValidNumber(String input) {
        return Pattern.matches("-?\\d+(\\.\\d+)?(e-?\\d+)?", input);
    }

    private static double roundNumber(double number, int decimalPlaces) {
        double factor = Math.pow(10, decimalPlaces);
        return Math.round(number * factor) / factor;
    }
}
