            raise ValueError("Path with the specified ID does not exist")
        del self.paths[path_id]

    def get_path(self, path_id):
        if path_id not in self.paths:
            raise ValueError("Path with the specified ID does not exist")
        return self.paths[path_id]

    def find_longest_path(self):
        if not self.paths:
            return None
        longest_path = max(self.paths, key=lambda path: len(path))
        return longest_path
