public class PrimeFactorsSum {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter the first positive prime number: ");
        int num1 = input.nextInt();
        System.out.print("Enter the second positive prime number: ");
        int num2 = input.nextInt();

        int sum = primeFactorsSum(num1) + primeFactorsSum(num2);

        System.out.println("The sum of prime factors is: " + sum);
    }

    public static int primeFactorsSum(int number) {
        int sum = 0;

        for (int i = 2; i <= number; i++) {
            while (number % i == 0) {
                sum += i;
                number /= i;
            }
        }
        return sum;
    }
}

