# Define a class called 'Node' for individual nodes in a Binary Search Tree (BST)
class Node:
    # Each node has a data attribute for storing the value and attributes for left and right child nodes
    def __init__(self, data):
        self.left = None
        self.right = None
        self.data = data

    # Define a function called 'insert' to add data to the BST. If the current node's data is None, it is replaced with the new data.
    # If the current node's data is not None, the function compares the new data to the current node's data.
    # If the new data is less than the current node's data, it is added to the left. If it is greater, it is added to the right.
    def insert(self, data):
        if self.data:
            if data < self.data:
                if self.left is None:
                    self.left = Node(data)
                else:
                    self.left.insert(data)
            elif data > self.data:
                if self.right is None:
                    self.right = Node(data)
                else:
                    self.right.insert(data)
        else:
            self.data = data

    # Define a function called 'printInOrder' for an inorder tree traversal. This prints the data in the nodes of the BST in ascending order.
    def printInOrder(self):
        if self.left:
            self.left.printInOrder()

        print(self.data),

        if self.right:
            self.right.printInOrder()

# Create a root node
root = Node(3)

# Insert the other elements from the array
for i in [8, 4, 5, 2, 10, 7]:
    root.insert(i)

