import java.util.Arrays;

public class AnagramChecker {

    public boolean isAnagram(String string1, String string2) {
        // Remove whitespace, convert to lowercase and remove punctuation
        String cleanString1 = removePunctuationAndWhitespace(string1).toLowerCase();
        String cleanString2 = removePunctuationAndWhitespace(string2).toLowerCase();

        // Check if lengths are equal
        if (cleanString1.length() != cleanString2.length()) {
            return false;
        }

        // Convert strings to char arrays
        char[] array1 = cleanString1.toCharArray();
        char[] array2 = cleanString2.toCharArray();

        // Sort the arrays
        Arrays.sort(array1);
        Arrays.sort(array2);

        // Compare arrays
        return Arrays.equals(array1, array2);
    }

    private String removePunctuationAndWhitespace(String input) {
        return input.replaceAll("[\\p{P}\\p{S}]", "").replaceAll("\\s", "");
    }

}
```
