bool isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

std::vector<int> filterPrimes(const std::vector<int>& arr) {
    std::vector<int> primes;
    for (int i = arr.size() - 1; i >= 0; i--) {
        if (isPrime(arr[i])) {
            primes.push_back(arr[i]);
        }
    }
    return primes;
}

