import java.io.IOException;
import java.util.StringTokenizer;

import org.apache.hadoop.fs.Path;
import org.apache.hadoop.io.DoubleWritable;
import org.apache.hadoop.io.Text;
import org.apache.hadoop.mapreduce.Job;
import org.apache.hadoop.mapreduce.Mapper;
import org.apache.hadoop.mapreduce.Reducer;
import org.apache.hadoop.mapreduce.lib.input.FileInputFormat;
import org.apache.hadoop.mapreduce.lib.output.FileOutputFormat;

public class AverageValueCalculation {

  public static class AverageMapper
       extends Mapper<Object, Text, Text, DoubleWritable>{

    private final static DoubleWritable value = new DoubleWritable();
    private Text word = new Text();

    public void map(Object key, Text record, Context context
                    ) throws IOException, InterruptedException {
      StringTokenizer itr = new StringTokenizer(record.toString());
      while (itr.hasMoreTokens()) {
        word.set("average");
        value.set(Double.parseDouble(itr.nextToken()));
        context.write(word, value);
      }
    }
  }

  public static class AverageReducer
       extends Reducer<Text,DoubleWritable,Text,DoubleWritable> {
    private DoubleWritable result = new DoubleWritable();

    public void reduce(Text key, Iterable<DoubleWritable> values,
                       Context context
                       ) throws IOException, InterruptedException {
      double sum = 0;
      int count = 0;
      for (DoubleWritable val : values) {
        sum += val.get();
        count++;
      }
      result.set(sum / count);
      context.write(key, result);
    }
  }

  public static void main(String[] args) throws Exception {
    Job job = Job.getInstance();
    job.setJarByClass(AverageValueCalculation.class);
    job.setMapperClass(AverageMapper.class);
    job.setCombinerClass(AverageReducer.class);
    job.setReducerClass(AverageReducer.class);
    job.setOutputKeyClass(Text.class);
    job.setOutputValueClass(DoubleWritable.class);
    FileInputFormat.addInputPath(job, new Path(args[0]));
    FileOutputFormat.setOutputPath(job, new Path(args[1]));
    System.exit(job.waitForCompletion(true) ? 0 : 1);
  }
}
```

