    public KeyCode adjustLowerKey = KeyCode.DownArrow;
    [Tooltip("Nudges the Eye Recession closer by 1 millimeter.")]
    public KeyCode adjustCloserKey = KeyCode.RightBracket;
    [Tooltip("Nudges the Eye Recession farther by 1 millimeter.")]
    public KeyCode adjustFartherKey = KeyCode.LeftBracket;

    private void Update()
    {
        HandleAdjustmentHotkeys();
    }

    private void HandleAdjustmentHotkeys()
    {
        if (Input.GetKeyDown(adjustWiderKey))
        {
            AdjustIPD(1); // Nudge the IPD wider by 1 millimeter
        }
        else if (Input.GetKeyDown(adjustNarrowerKey))
        {
            AdjustIPD(-1); // Nudge the IPD narrower by 1 millimeter
        }
        else if (Input.GetKeyDown(adjustHigherKey))
        {
            AdjustEyeHeight(1); // Nudge the Eye Height higher by 1 millimeter
        }
        else if (Input.GetKeyDown(adjustLowerKey))
        {
            AdjustEyeHeight(-1); // Nudge the Eye Height lower by 1 millimeter
        }
        else if (Input.GetKeyDown(adjustCloserKey))
        {
            AdjustEyeRecession(1); // Nudge the Eye Recession closer by 1 millimeter
        }
        else if (Input.GetKeyDown(adjustFartherKey))
        {
            AdjustEyeRecession(-1); // Nudge the Eye Recession farther by 1 millimeter
        }
    }

    private void AdjustIPD(float amount)
    {
        // Adjust the inter-pupillary distance (IPD) using the ARRaytracer for the right eye
        rightEyeARRaytracer.AdjustIPD(amount);
    }

    private void AdjustEyeHeight(float amount)
    {
        // Adjust the eye height by moving the camera or eye position
        transform.position += new Vector3(0, amount, 0);
    }

    private void AdjustEyeRecession(float amount)
    {
        // Adjust the eye recession by moving the camera or eye position along the forward axis
        transform.position += transform.forward * amount;
    }
}
