Here is a C program that sorts a list of words in alphabetical order, ignoring punctuation marks, removes duplicates, and outputs the sorted list in reverse order:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function to remove duplicate words from the sorted list
int removeDuplicates(char* words[], int n) {
    if (n == 0) return 0;

    int index = 0;

    for (int i = 1; i < n; i++) {
        if (strcmp(words[index], words[i]) != 0) {
            index++;
            words[index] = words[i];
        }
    }

    return index + 1;
}

// Function to sort the list of words
void sortWords(char* words[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            // Convert both words to lowercase for case-insensitive comparison
            char* word1 = words[j];
            char* word2 = words[j + 1];
            for (int k = 0; word1[k] != '\0'; k++) {
                word1[k] = tolower(word1[k]);
            }
            for (int k = 0; word2[k] != '\0'; k++) {
                word2[k] = tolower(word2[k]);
            }

            if (strcmp(word1, word2) > 0) {
                // Swap the words
                char* temp = words[j];
                words[j] = words[j + 1];
                words[j + 1] = temp;
            }
        }
    }
}

int main() {
    char* words[] = {"apple", "orange", "Banana", "banana", "grape", "APPLE", "grape", "cherry", "Cherry"};
    int n = sizeof(words) / sizeof(words[0]);

    // Sort the words
    sortWords(words, n);

    // Remove duplicates
    int newLength = removeDuplicates(words, n);

    // Output the sorted list in reverse order
    for (int i = newLength - 1; i >= 0; i--) {
        printf("%s\n", words[i]);
    }

    return 0;
}
