function isPrime(num) {
  if (num <= 1) return false;
  if (num === 2) return true;
  if (num % 2 === 0) return false;

  const sqrt = Math.sqrt(num);
  for (let i = 3; i <= sqrt; i += 2) {
    if (num % i === 0) {
      return false;
    }
  }

  return true;
}

function generateFibonacciPrimes(n) {
  const fibonacciPrimes = [];
  let sum = 0;

  let a = 0;
  let b = 1;
  let index = 1;

  while (fibonacciPrimes.length < n) {
    const fibonacciNumber = a + b;
    if (isPrime(fibonacciNumber) && isPrime(index)) {
      fibonacciPrimes.push(fibonacciNumber);
      sum += fibonacciNumber;
    }

    a = b;
    b = fibonacciNumber;
    index++;
  }

  return { fibonacciPrimes, sum };
}

const { fibonacciPrimes, sum } = generateFibonacciPrimes(1000);
