      return Math.floor(Math.random() * (max - min + 1) + min);
    }

    // Function to generate the table
    function generateTable() {
      var table = document.getElementById("myTable");
      var rows = 1000000;
      var cols = 100;

      // Generate table rows
      for (var i = 0; i < rows; i++) {
        var row = table.insertRow(i);

        // Generate table cells
        for (var j = 0; j < cols; j++) {
          var cell = row.insertCell(j);
          cell.innerHTML = getRandomNumber(1, 100);
        }
      }
    }

    // Function to sort the table by column
    function sortTable(col) {
      var table, rows, switching, i, x, y, shouldSwitch;
      table = document.getElementById("myTable");
      switching = true;
      while (switching) {
        switching = false;
        rows = table.rows;
        for (i = 0; i < (rows.length - 1); i++) {
          shouldSwitch = false;
          x = parseInt(rows[i].getElementsByTagName("TD")[col].innerHTML);
          y = parseInt(rows[i + 1].getElementsByTagName("TD")[col].innerHTML);
          if (x > y) {
            shouldSwitch = true;
            break;
          }
        }
        if (shouldSwitch) {
          rows[i].parentNode.insertBefore(rows[i + 1], rows[i]);
          switching = true;
        }
      }
    }

    // Function to handle pagination
    function paginate() {
      var table = document.getElementById("myTable");
      var rowsPerPage = 50;
      var currentPage = 1;
      var totalPages = Math.ceil(table.rows.length / rowsPerPage);

      // Show initial page
      showPage(currentPage);

      // Function to show a specific page
      function showPage(page) {
        var startRow = (page - 1) * rowsPerPage;
        var endRow = startRow + rowsPerPage;

        // Hide all rows
        for (var i = 0; i < table.rows.length; i++) {
          table.rows[i].style.display = "none";
        }

        // Show rows for current page
        for (var j = startRow; j < endRow; j++) {
          if (table.rows[j]) {
            table.rows[j].style.display = "";
          }
        }
      }

      // Function to navigate to previous page
      function prevPage() {
        if (currentPage > 1) {
          currentPage--;
          showPage(currentPage);
        }
      }

      // Function to navigate to next page
      function nextPage() {
        if (currentPage < totalPages) {
          currentPage++;
          showPage(currentPage);
        }
      }

      // Add event listeners to prev and next buttons
      document.getElementById("prevBtn").addEventListener("click", prevPage);
      document.getElementById("nextBtn").addEventListener("click", nextPage);
    }

    // Function to search and highlight cells
    function searchTable() {
      var input, filter, table, rows, cells, i, j;
      input = document.getElementById("searchInput");
      filter = input.value.toUpperCase();
      table = document.getElementById("myTable");
      rows = table.getElementsByTagName("tr");

      // Loop through all rows and cells, hide non-matching cells
      for (i = 0; i < rows.length; i++) {
        cells = rows[i].getElementsByTagName("td");
        for (j = 0; j < cells.length; j++) {
          if (cells[j].innerHTML.toUpperCase().indexOf(filter) > -1) {
            rows[i].style.display = "";
            cells[j].classList.add("highlight");
          } else {
            rows[i].style.display = "none";
            cells[j].classList.remove("highlight");
          }
        }
      }
    }
