        word = word.replaceAll("[^\\p{IsAlphabetic}]", "");
        return word;
    }

    private static boolean isStopword(String word) {
        String[] stopwords = {"the", "and", "in", "a"};
        for (String stopword : stopwords) {
            if (word.equals(stopword)) {
                return true;
            }
        }
        return false;
    }

