```python
from typing import Dict, List, Tuple, Union
from heapq import *

def add_number(num, lowers, highers):
    if not lowers or num < -lowers[0]:
        heappush(lowers, -num)
    else:
        heappush(highers, num)

def rebalance(lowers, highers):
    if len(lowers) - len(highers) >= 2:
        heappush(highers, -heappop(lowers))
    elif len(highers) - len(lowers) >= 2:
        heappush(lowers, -heappop(highers))

def get_medians(lowers, highers):
    if len(lowers) == len(highers):
        return (-lowers[0] + highers[0]) / 2
    elif len(lowers) > len(highers):
        return -lowers[0]
    else:
        return highers[0]

def compute_median(data):
    if isinstance(data, dict):
        data = list(data.values())
    lowers, highers = [], []
    for num in data:
        add_number(num, lowers, highers)
        rebalance(lowers, highers)
    return get_medians(lowers, highers)

def robust_median(data1: Union[Dict, List[Tuple]], data2: Union[Dict, List[Tuple]]):
    if not data1 or not data2:
        raise ValueError("One of the datasets is empty.")

    if isinstance(data1, dict):
        data1 = list(data1.values())
    if isinstance(data2, dict):
        data2 = list(data2.values())

    data1 = [item for sublist in data1 for item in sublist]
    data2 = [item for sublist in data2 for item in sublist]

    combined_data = data1 + data2

    return compute_median(combined_data)
```
This version of the program applies a heap-based algorithm which offers more efficiency, especially when dealing with larger datasets. The median is computed by maintaining two heaps for storing the lower and higher halves of the dataset. With this, the median can be identified directly from the heap roots, providing an efficient solution for large-scale data.

