def construct_url(protocol, domain, subdomains=None, paths=None, query_params=None, fragment=None):
    try:
        # prepare the subdomain component only if it's a list of strings
        subdomain_component = ''
        if subdomains:
            if isinstance(subdomains, list) and all(isinstance(i, str) for i in subdomains):
                subdomain_component = '.'.join(subdomains) + '.'
            else:
                raise ValueError('Subdomains must be a list of strings.')

        # prepare the path component only if it's a list of strings
        path_component = ''
        if paths:
            if isinstance(paths, list) and all(isinstance(i, str) for i in paths):
                path_component = '/' + '/'.join(paths)
            else:
                raise ValueError('Paths must be a list of strings.')

        # prepare the query string only if it's a dictionary
        query_string = ''
        if query_params:
            if isinstance(query_params, dict):
                query_string = '?' + urlencode(query_params)
            else:
                raise ValueError('Query parameters must be a dictionary.')

        # Preparing the fragment
        fragment_component = ''
        if fragment:
            if isinstance(fragment, str):
                fragment_component = '#' + fragment
            else:
                raise ValueError('Fragment identifier must be a string.')

        # merge all the components to form the full url
        url = f'{protocol}://{subdomain_component}{domain}{path_component}{query_string}{fragment_component}'

        # encode special characters as per RFC3986
        encoded_url = quote(url, safe=':/#?=&')

    except Exception as e:
        return str(e)

    return url, encoded_url


