# Create a LinkedList class to chain the nodes together
class LinkedList:
    # On initializing the LinkedList, its head is set to None.
    def __init__(self):
        self.head = None

    # Method to insert a new node at the end of the LinkedList
    def insert(self, data):
        # If the LinkedList is empty (i.e., head == None), set the head as the new Node. The 'next' of this node will be None as there are no other nodes in the list.
        if not self.head:
            self.head = Node(data)
        else:
            # If the LinkedList is not empty, traverse the list till the end (till cur.next is not None), and then insert the new Node at the end of the list.
            cur = self.head
            while cur.next:
                cur = cur.next
            cur.next = Node(data)
