```java
public class Main {

    public static boolean isPalindrome(String str) {
        //Handle null and empty string inputs
        if (str == null || str.isEmpty()) {
            return true;
        }
        //Strip out punctuation and whitespaces
        String usefulChars = str.replaceAll("[^A-Za-z]", "");
        //Recurse on the cleaned-up string
        return isValidPalindrome(usefulChars);
    }

    private static boolean isValidPalindrome(String str) {
        int length = str.length();
        if (length <= 1) {
            return true;
        }
        //Next character comparison
        if (str.charAt(0) != str.charAt(length - 1)) {
            return false;
        }
        //Recursive step
        return isValidPalindrome(str.substring(1,length - 1));
    }

    public static void main(String[] args) {
        System.out.println(isPalindrome("Able , was I saw elba"));  // true
        System.out.println(isPalindrome("A man, a plan, a canal, Panama"));  // false
    }
}
