public class PrimeNumbersCalculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int num1, num2, num3, limit;
        int sum = 0;

        // Prompt user for input
        System.out.print("Enter the first positive integer: ");
        num1 = scanner.nextInt();

        System.out.print("Enter the second positive integer: ");
        num2 = scanner.nextInt();

        System.out.print("Enter the third positive integer: ");
        num3 = scanner.nextInt();

        System.out.print("Enter the maximum limit: ");
        limit = scanner.nextInt();

        // Validate user inputs
        if (num1 < 0 || num2 < 0 || num3 < 0 || limit < (Math.max(Math.max(num1, num2), num3) - Math.min(Math.min(num1, num2), num3))) {
            System.out.println("Invalid input. Please make sure all numbers are positive and the maximum limit is greater than the difference between the three numbers.");
            return;
        }

        // Calculate and display the sum of prime numbers
        int currentNumber = Math.min(Math.min(num1, num2), num3);
        while (currentNumber >= 0 && currentNumber <= limit) {
            if (isPrime(currentNumber)) {
                sum += currentNumber;
            }
            currentNumber++;
        }

        System.out.println("The sum of prime numbers between the given three numbers and less than or equal to the maximum limit is: " + sum);
    }

    // Helper method to check if a number is prime
    private static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }
}
