public static double calculateWeightedAverage(Integer[] numbers, Double[] weights) {
    if (numbers == null || weights == null) {
        throw new NullPointerException("Arrays cannot be null");
    }

    int numbersLength = numbers.length;
    int weightsLength = weights.length;

    if (numbersLength == 0 || weightsLength == 0) {
        return 0;
    }

    if (numbersLength != weightsLength) {
        throw new IllegalArgumentException("Arrays must have the same length");
    }

    double weightedSum = 0;
    double sumOfWeights = 0;

    for (int i = 0; i < numbersLength; i++) {
        if (numbers[i] == null || weights[i] == null) {
            throw new NullPointerException("Array elements cannot be null");
        }

        if (weights[i] < 0) {
            throw new IllegalArgumentException("Weights cannot be negative");
        }

        weightedSum += numbers[i] * weights[i];
        sumOfWeights += weights[i];
    }

    return weightedSum / sumOfWeights;
}
