```java
public class HTMLEntityParser {
    public static void main(String[] args) {
        String html = "This is an example: 5 &lt; 10 and 7 &gt; 3";
        System.out.println(parseHTML(html));
    }

    public static String parseHTML(String html) {
        StringBuilder stringBuilder = new StringBuilder();
        for (int i = 0; i < html.length(); i++) {
            char c = html.charAt(i);
            if (c != '&') {
                stringBuilder.append(c);
            } else {
                int j = html.indexOf(';', i);
                char charUnescape = unescape2Char(html.substring(i, j + 1));
                if (charUnescape != 0) {
                    stringBuilder.append(charUnescape);
                    i = j; // Move the index to the end of the HTML entity
                } else {
                    stringBuilder.append(html, i, j + 1); // Append the original HTML entity
                    i = j; // Move the index to the end of the HTML entity
                }
            }
        }
        return stringBuilder.toString();
    }

    public static char unescape2Char(String entity) {
        switch (entity) {
            case "&lt;":
                return '<';
            case "&gt;":
                return '>';
            case "&amp;":
                return '&';
            case "&quot;":
                return '"';
            case "&apos;":
                return '\'';
            default:
                if (entity.startsWith("&#") && entity.endsWith(";")) {
                    try {
                        int asciiValue = Integer.parseInt(entity.substring(2, entity.length() - 1));
                        if (asciiValue >= 0 && asciiValue <= 127) {
                            return (char) asciiValue;
                        }
                    } catch (NumberFormatException e) {
                        // Invalid decimal ASCII value format
                    }
                }
                return 0; // Invalid or unsupported entity
        }
    }
}
```

