import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class SphereCalculator {
    private static final double PI = Math.PI;
    private static final double CONVERSION_FACTOR = 0.0254; // Conversion factor for inches to meters

    private static Map<Double, Double> volumeCache = new HashMap<>();
    private static Map<Double, Double> surfaceAreaCache = new HashMap<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        boolean exit = false;

        while (!exit) {
            System.out.println("1. Calculate volume");
            System.out.println("2. Calculate surface area");
            System.out.println("3. Exit");
            System.out.print("Choose an option: ");
            int option = scanner.nextInt();

            switch (option) {
                case 1:
                    calculateVolume(scanner);
                    break;
                case 2:
                    calculateSurfaceArea(scanner);
                    break;
                case 3:
                    exit = true;
                    break;
                default:
                    System.out.println("Invalid option! Please choose a valid option.");
                    break;
            }

            System.out.println();
        }

        scanner.close();
    }

    private static void calculateVolume(Scanner scanner) {
        double radius = getValidRadius(scanner);
        double volume;

        if (volumeCache.containsKey(radius)) {
            volume = volumeCache.get(radius);
        } else {
            volume = (4.0 / 3.0) * PI * Math.pow(radius, 3);
            volumeCache.put(radius, volume);
        }

        System.out.println("Volume of the sphere with radius " + radius + " is: " + volume);
    }

    private static void calculateSurfaceArea(Scanner scanner) {
        double radius = getValidRadius(scanner);
        double surfaceArea;

        if (surfaceAreaCache.containsKey(radius)) {
            surfaceArea = surfaceAreaCache.get(radius);
        } else {
            surfaceArea = 4 * PI * Math.pow(radius, 2);
            surfaceAreaCache.put(radius, surfaceArea);
        }

        System.out.println("Surface area of the sphere with radius " + radius + " is: " + surfaceArea);
    }

    private static double getValidRadius(Scanner scanner) {
        double radius = -1;

        while (radius <= 0) {
            System.out.print("Enter the radius of the sphere: ");
            if (scanner.hasNextDouble()) {
                radius = scanner.nextDouble();
                if (radius <= 0) {
                    System.out.println("Invalid radius! Please enter a positive value.");
                }
            } else {
                System.out.println("Invalid input! Please enter a valid radius.");
                scanner.next(); // Clear the invalid input
            }
        }

        int unitOption = chooseUnitOption(scanner);
        radius = convertRadiusToMeters(radius, unitOption);

        return radius;
    }

    private static int chooseUnitOption(Scanner scanner) {
        System.out.println("Choose the unit of the radius:");
        System.out.println("1. Inches");
        System.out.println("2. Centimeters");
        System.out.println("3. Meters");
        System.out.print("Enter the unit option: ");
        int unitOption = scanner.nextInt();

        return unitOption;
    }

    private static double convertRadiusToMeters(double radius, int unitOption) {
        switch (unitOption) {
            case 1:
                radius *= CONVERSION_FACTOR;
                break;
            case 2:
                radius /= 100;
                break;
            case 3:
                // No conversion needed
                break;
            default:
                System.out.println("Invalid unit option! Using meters as the default unit.");
                break;
        }

        return radius;
    }
}
