  const unique = [];

  // Helper function to check if an element exists in the unique array
  function existsInUnique(element) {
    let isUnique = true;
    for (let i = 0; i < unique.length; i++) {
      if (element === unique[i]) {
        isUnique = false;
        break;
      }
    }
    return isUnique;
  }

  // Iterate over the array and add unique elements to the unique array
  arr.forEach((element) => {
    if (existsInUnique(element)) {
      unique.push(element);
    }
  });

