  // Iterate through each character in the string
  for (var i = 0; i < str.length; i++) {
    var char = str.charAt(i);

    // Skip spaces and special characters
    if (char.match(/[a-z]/i)) {
      // If the character already exists in the charFreq object, increment its frequency by 1
      if (charFreq[char]) {
        charFreq[char]++;
      } else {
        // Otherwise, add the character to the charFreq object with frequency 1
        charFreq[char] = 1;
      }
    }
  }

  var mostFreqChar = '';
  var highestFreq = 0;

  // Iterate through the charFreq object to find the character with the highest frequency
  for (var char in charFreq) {
    if (charFreq[char] > highestFreq) {
      mostFreqChar = char;
      highestFreq = charFreq[char];
    }
  }

  return mostFreqChar;
}
```

Here's an example usage of the function:

