Write an algorithm to find the maximum subarray sum within the provided input array. The input array may contain negative numbers. The algorithm should have a time complexity of O(n log n), where n is the size of the input array.

Reference code:
```
def find_max_subarray_sum(arr):
    if len(arr) == 0:
        return 0

    def find_max_crossing_subarray(arr, low, mid, high):
        left_sum = float('-inf')
        sum = 0
        for i in range(mid, low-1, -1):
            sum += arr[i]
            if sum > left_sum:
                left_sum = sum
        right_sum = float('-inf')
        sum = 0
        for i in range(mid+1, high+1):
            sum += arr[i]
            if sum > right_sum:
                right_sum = sum
        return left_sum + right_sum

    def find_max_subarray_sum_helper(arr, low, high):
        if low == high:
            return arr[low]
        mid = (low + high) // 2
        left_sum = find_max_subarray_sum_helper(arr, low, mid)
        right_sum = find_max_subarray_sum_helper(arr, mid+1, high)
        cross_sum = find_max_crossing_subarray(arr, low, mid, high)
        return max(left_sum, right_sum, cross_sum)

    return find_max_subarray_sum_helper(arr, 0, len(arr)-1)
```

