function findThirdSmallestDistinctNumber(arr) {
  // Sort the array in ascending order
  arr.sort((a, b) => a - b);

  let distinctNumbers = [];
  for (let i = 0; i < arr.length; i++) {
    // Check if the current number is already in the distinctNumbers array
    if (distinctNumbers.indexOf(arr[i]) === -1) {
      distinctNumbers.push(arr[i]);
    }

    // Check if we have found the third smallest distinct number
    if (distinctNumbers.length === 3) {
      return distinctNumbers[2];
    }
  }

  // Return undefined if there are not enough distinct numbers
  return undefined;
}

