```php
function isPrime($n)
{
    // Handling edge cases
    if (!is_int($n) || $n <= 1) {
        return false;
    }

    // Recursive base case
    if ($n == 2) {
        return true;
    }

    // Check if the number is divisible by any smaller odd number
    if ($n % 2 == 0) {
        return false;
    }

    return isPrimeRecursive($n, 3); // Call the recursive helper function
}

function isPrimeRecursive($n, $divisor)
{
    if ($divisor * $divisor > $n) {
        return true;
    }

    if ($n % $divisor == 0) {
        return false;
    }

    return isPrimeRecursive($n, $divisor + 2);
}
```

