def convert_json_to_xml(json_string):
    output = ["<root>"]

    stack = [{"tag": "root", "data": json_string, "index": 0}]

    def add_tag(tag_name, value=None, open_tag=True):
        if open_tag:
            if value is None:
                output.append("<{tag}>".format(tag=tag_name))
            else:
                output.append("<{tag}>{value}".format(tag=tag_name, value=str(value)))
        else:
            output.append("</{tag}>".format(tag=tag_name))

    def parse_data(data, tag_name):
        if isinstance(data, dict):
            add_tag(tag_name)
            for k, v in data.items():
                parse_data(v, k)
            add_tag(tag_name, open_tag=False)
        elif isinstance(data, list):
            for item in data:
                parse_data(item, tag_name)
        else:
            add_tag(tag_name, value=data)

    while len(stack) > 0:
        current = stack.pop()
        parse_data(current["data"], current["tag"])

    output.append("</root>")
    return "".join(output)
```
