function deleteCookies(domain, threshold) {
  const cookies = document.cookie.split(";");

  let count = 0;

  const now = new Date().getTime();
  const thresholdDate = now - (threshold * 24 * 60 * 60 * 1000); // Convert threshold to milliseconds

  for (let i = 0; i < cookies.length; i++) {
    const cookie = cookies[i].trim();

    // Check if the cookie belongs to the specified domain
    if (cookie.startsWith(domain)) {
      const cookieParts = cookie.split("=");
      const cookieName = cookieParts[0];

      // Check if the cookie has an expiration date
      if (cookieParts.length > 1) {
        const cookieValue = cookieParts[1];
        const expiration = parseInt(cookieValue);

        // Check if the expiration date is older than the threshold
        if (expiration && expiration < thresholdDate) {
          // Delete the cookie
          document.cookie = `${cookieName}=; expires=Thu, 01 Jan 1970 00:00:00 UTC; domain=${domain}; path=/`;
          count++;
        }
      }
    }
  }

  return count;
}
