class InvalidDeepCloneableException extends Exception {
    public InvalidDeepCloneableException(String message) {
        super(message);
    }
}

interface DeepCloneable {
    Object deepClone() throws CloneNotSupportedException;
}

class ExampleObject implements DeepCloneable {
    private int value;

    public ExampleObject(int value) {
        this.value = value;
    }

    @Override
    public Object deepClone() throws CloneNotSupportedException {
        return new ExampleObject(this.value);
    }
}

public class ArrayCloneExample {
    public static void main(String[] args) {
        ExampleObject[] originalArray = new ExampleObject[3];
        originalArray[0] = new ExampleObject(1);
        originalArray[1] = new ExampleObject(2);
        originalArray[2] = new ExampleObject(3);

        ExampleObject[] clonedArray = cloneArray(originalArray);
        System.out.println(Arrays.toString(clonedArray));
    }

    public static ExampleObject[] cloneArray(ExampleObject[] originalArray) {
        ExampleObject[] clonedArray = new ExampleObject[originalArray.length];
        for (int i = 0; i < originalArray.length; i++) {
            try {
                if (!(originalArray[i] instanceof DeepCloneable)) {
                    throw new InvalidDeepCloneableException("Object at index " + i + " does not implement DeepCloneable interface");
                }
                clonedArray[i] = (ExampleObject) originalArray[i].deepClone();
            } catch (CloneNotSupportedException e) {
                System.out.println("Warning: Object at index " + i + " failed to clone. Skipping.");
            } catch (InvalidDeepCloneableException e) {
                System.out.println(e.getMessage());
            }
        }
        return clonedArray;
    }
}
