            return False
    return True

# Function to generate the spiral pattern
def generate_spiral(n, direction, start):
    # Initialize variables
    pattern = [[0] * n for _ in range(n)]
    num = 1
    row, col = start[0], start[1]
    row_dir, col_dir = direction[0], direction[1]
    steps = n - 1

    # Generate the spiral pattern
    for _ in range(math.ceil(n / 2)):
        for _ in range(steps):
            if is_prime(num):
                pattern[row][col] = num
                num += 1
            row += row_dir
            col += col_dir

        row_dir, col_dir = col_dir, -row_dir
        steps -= 1

    # Add the last prime number to the center of the pattern
    if is_prime(num):
        pattern[row][col] = num

    return pattern

# Function to calculate the sum and product of the elements in the pattern
def calculate_sum_product(pattern):
    total_sum = 0
    total_product = 1
    for row in pattern:
        for num in row:
            total_sum += num
            total_product *= num
    return total_sum, total_product

