import java.util.*;

public class MeanMedianMode {

    public static double calculateMean(List<Double> numbers) {
        double sum = 0;
        for (double num : numbers) {
            sum += num;
        }
        return sum / numbers.size();
    }

    public static double calculateMedian(List<Double> numbers) {
        Collections.sort(numbers);
        int size = numbers.size();
        if (size % 2 == 0) {
            return (numbers.get(size / 2 - 1) + numbers.get(size / 2)) / 2;
        } else {
            return numbers.get(size / 2);
        }
    }

    public static List<Double> calculateMode(List<Double> numbers) {
        Map<Double, Integer> frequencyMap = new HashMap<>();
        int maxFrequency = 0;
        for (double num : numbers) {
            int frequency = frequencyMap.getOrDefault(num, 0) + 1;
            frequencyMap.put(num, frequency);
            maxFrequency = Math.max(maxFrequency, frequency);
        }

        List<Double> modes = new ArrayList<>();
        for (Map.Entry<Double, Integer> entry : frequencyMap.entrySet()) {
            if (entry.getValue() == maxFrequency) {
                modes.add(entry.getKey());
            }
        }

        return modes;
    }

    public static void main(String[] args) {
        List<Double> numbers = Arrays.asList(4.0, 2.0, 7.0, 4.0, 9.0, 2.0, 1.0, 7.0, 4.0);

        double mean = calculateMean(numbers);
        double median = calculateMedian(numbers);
        List<Double> mode = calculateMode(numbers);

        System.out.println("Mean: " + mean);
        System.out.println("Median: " + median);
        System.out.println("Mode: " + mode);
    }
}

