import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.jpa.repository.JpaRepository;

public class PaginationUtility {
    private final JpaRepository repository;

    public PaginationUtility(JpaRepository repository) {
        this.repository = repository;
    }

    public <T> Page<T> paginateEntities(Class<T> entityClass, String searchField, String searchString, Pageable pageable) {
        int page = (pageable.getPageNumber() == 0) ? 0 : (pageable.getPageNumber() - 1);
        pageable = PageRequest.of(page, pageable.getPageSize());
        String methodName = "findBy" + searchField.substring(0, 1).toUpperCase() + searchField.substring(1) + "Containing";
        return repository.getClass().getMethod(methodName, String.class, Pageable.class)
                .invoke(repository, searchString, pageable);
    }
