    public void add(int value) {
        Node newNode = new Node(value);

        if (head == null) {
            head = newNode;
        } else {
            Node current = head;
            while (current.next != null) {
                current = current.next;
            }
            current.next = newNode;
        }

        length++;
    }

    public void removeLeadingZeros() {
        Node current = head;
        while (current != null && current.value == 0) {
            head = current.next;
            current = current.next;
            length--;
        }
    }

    public void print() {
        Node current = head;
        while (current != null) {
            System.out.print(current.value + " -> ");
            current = current.next;
        }
        System.out.println("null");
    }
}

class Calculator {
    public static LinkedList sum(LinkedList list1, LinkedList list2) {
        LinkedList result = new LinkedList();
        int carry = 0;

        Node current1 = list1.head;
        Node current2 = list2.head;

        while (current1 != null || current2 != null || carry != 0) {
            int value1 = (current1 != null) ? current1.value : 0;
            int value2 = (current2 != null) ? current2.value : 0;

            int sum = value1 + value2 + carry;

            carry = sum / 10;
            sum = sum % 10;

            result.add(sum);

            if (current1 != null) {
                current1 = current1.next;
            }

            if (current2 != null) {
                current2 = current2.next;
            }
        }

        return result;
    }

    public static LinkedList difference(LinkedList list1, LinkedList list2) {
        LinkedList result = new LinkedList();
        int borrow = 0;

        Node current1 = list1.head;
        Node current2 = list2.head;

        while (current1 != null || current2 != null) {
            int value1 = (current1 != null) ? current1.value : 0;
            int value2 = (current2 != null) ? current2.value : 0;

            value1 -= borrow;

            if (value1 < value2) {
                value1 += 10;
                borrow = 1;
            } else {
                borrow = 0;
            }

            int difference = value1 - value2;

            result.add(difference);

            if (current1 != null) {
                current1 = current1.next;
            }

            if (current2 != null) {
                current2 = current2.next;
            }
        }

        return result;
    }

    public static LinkedList product(LinkedList list1, LinkedList list2) {
        LinkedList result = new LinkedList();

        Node current1 = list1.head;
        Node current2 = list2.head;

        int zeros = 0;

        while (current2 != null) {
            LinkedList temp = new LinkedList();
            int carry = 0;

            for (int i = 0; i < zeros; i++) {
                temp.add(0);
            }

            while (current1 != null || carry != 0) {
                int value1 = (current1 != null) ? current1.value : 0;

                int product = (value1 * current2.value) + carry;

                carry = product / 10;
                product = product % 10;

                temp.add(product);

                if (current1 != null) {
                    current1 = current1.next;
                }
            }

            result = sum(result, temp);

            current1 = list1.head;
            current2 = current2.next;

            zeros++;
        }

        return result;
    }

    public static LinkedList quotient(LinkedList list1, LinkedList list2) {
        LinkedList result = new LinkedList();

        LinkedList remainder = new LinkedList();
        remainder.head = list1.head;
        remainder.length = list1.length;

        int zeros = list1.length - list2.length;

        for (int i = 0; i < zeros; i++) {
            result.add(0);
        }

        LinkedList temp = new LinkedList();

        while (remainder.length >= list2.length) {
            temp.head = remainder.head;
            temp.length = remainder.length;

            int count = 0;

            while (!isNegative(difference(temp, list2))) {
                temp = difference(temp, list2);
                count++;
            }

            result.add(count);

            remainder.head = temp.head;
            remainder.length = temp.length;

            temp.head = null;
            temp.length = 0;

            zeros--;
        }

        return result;
    }

    public static LinkedList remainder(LinkedList list1, LinkedList list2) {
        LinkedList temp = quotient(list1, list2);
        LinkedList result = difference(list1, product(temp, list2));

        return result;
    }

    private static boolean isNegative(LinkedList list) {
        return list.head.value < 0;
    }
}

