import math

def smallest_prime(n):
    # Initialize the smallest prime number as 2
    smallest = 2

    # Check divisibility by 2, then move on to odd numbers
    while n % 2 == 0:
        n = n / 2

    # Start from 3 and iterate through numbers up to sqrt(n)
    # This works because a larger factor of n must be a multiple of a smaller factor, already checked
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            smallest = i
            n = n / i
    if n > 2:
        smallest = n
    return smallest

def check_prime(n):
    # Numbers less than 2 are not considered prime
    if n < 2:
        return f"{n} is neither a prime nor a composite number."

    # Use Sieve of Eratosthenes to check if input number is prime
    prime = [True for i in range(n + 1)]
    p = 2
    while p * p <= n:
        if prime[p] == True:
            for i in range(p * p, n + 1, p):
                prime[i] = False
        p += 1
    return prime[n]

def check_number(n):
    if check_prime(n):
        return 'Prime'
    else:
        return f"Composite with smallest prime factor {smallest_prime(n)}"

