```cpp
#include <iostream>

int evaluateExpression(int n) {
    if (n <= 0) {
        std::cout << "Error: n should be a positive integer." << std::endl;
        return 0;
    }
    if (n == 1) {
        return 1;
    }
    return (n * evaluateExpression(n - 1));
}

int main() {
    int n;
    std::cout << "Enter a positive integer: ";
    std::cin >> n;
    int result = evaluateExpression(n);
    if (result != 0) {
        std::cout << "Result: " << result << std::endl;
    }
    return 0;
}
