public static void main(String[] args) {
    int[] arr1 = {1, 3, 5, 7, 0, 0, 0}; // First sorted array with extra space for merging
    int[] arr2 = {2, 4, 6}; // Second sorted array
    int m = 4; // Number of elements in arr1
    int n = 3; // Number of elements in arr2

    mergeArrays(arr1, arr2, m, n);

    // Print the merged array
    for (int i = 0; i < m + n; i++) {
        System.out.print(arr1[i] + " ");
    }
}
