def expand_predicates(permission_map: Dict[str, List[str]]) -> Dict[str, List[str]]:
    expanded_map = {}

    def expand_predicate(predicate):
        if predicate not in expanded_map:
            expanded_map[predicate] = []
            for req_predicate in permission_map[predicate]:
                expanded_map[predicate].extend(expand_predicate(req_predicate))
            expanded_map[predicate] = list(set(expanded_map[predicate]))  # Remove duplicates
        return expanded_map[predicate]

    for predicate in permission_map:
        expand_predicate(predicate)

    return expanded_map
