import { promisify } from 'util';
import { parse } from 'node-html-parser';

const asyncParse = promisify(parse);

async function calculateTotalLinesOfCode(repositoryUrl: string): Promise<number> {
  const response = await fetch(repositoryUrl);
  const html = await response.text();
  const root = await asyncParse(html);

  const fileLinks = root.querySelectorAll('a.js-navigation-open');
  const tsFileLinks = fileLinks.filter(link => link.getAttribute('title').endsWith('.ts'));

  let totalLines = 0;

  for (const link of tsFileLinks) {
    const fileUrl = `https://github.com${link.getAttribute('href')}`;
    const fileResponse = await fetch(fileUrl);
    const fileText = await fileResponse.text();
    const lines = fileText.split('\n').filter(line => !line.trim().startsWith('//') && line.trim() !== '').length;
    totalLines += lines;
  }

  return totalLines;
}

