```python
def advanced_string_transform(a , b):
    # Function to check if one string is rotation of other
    def is_rotation(s1, s2):
        return len(s1) == len(s2) and s1 in s2 + s2

    # Function to check if one string is a subword of other
    def is_subword(s1, s2):
        return sorted(s1) == sorted(s2)  

    # Function to find minimum number of operations (insertions, deletions and substitutions) required to transform one string into other.
    def min_ops_transform(s1, s2):
        m = len(s1)
        n = len(s2)

        # Create a table to store results of subproblems
        dp = [[0 for x in range(n+1)] for x in range(m+1)]

        # Fill dp[][] in bottom up manner
        for i in range(m+1):
            for j in range(n+1):

                # If first string is empty, only option is to insert all characters of second string
                if i == 0:
                    dp[i][j] = j   

                # If second string is empty, only option is to remove all characters of first string
                elif j == 0:
                    dp[i][j] = i 

                # If last characters are same, ignore last character and recur for remaining string
                elif s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1]

                # If last character are different, consider all possibilities and find minimum
                else:
                    dp[i][j] = 1 + min(dp[i][j-1],     # Insert
                                       dp[i-1][j],     # Remove
                                       dp[i-1][j-1])   # Replace
        return dp[m][n]

    # first check for rotation and subwords
    if is_subword(a, b) or is_rotation(a, b):
        return True
    # then calculate min_ops_transform, return true if <= 1
    elif min_ops_transform(a, b) <= 1:
        return True
    else:
        return False
