```python
function sortStringsByLength(words) {
  // Step 1
  let filteredStrings = [];

  // Step 2
  for (let word of words) {
    // Step 3
    if (/[\d~`!#$%\^&*+=\-\[\]\\';,/{}|\\":<>\?]/g.test(word)) {
      continue;
    }

    // Step 4
    let lowercaseWord = word.toLowerCase();

    // Step 5
    filteredStrings.push(lowercaseWord);
  }

  // Step 6
  filteredStrings.sort((a, b) => b.length - a.length);

  // Step 7
  return filteredStrings;
}

