import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchItems, selectItem, selectAllItems, setSearchTerm } from './actions';

const ItemsList = () => {
  const dispatch = useDispatch();
  const { items, searchTerm, selectedItems, loading, error } = useSelector(state => state.items);

  useEffect(() => {
    dispatch(fetchItems());
  }, [dispatch]);

  const handleItemSelect = (itemId) => {
    dispatch(selectItem(itemId));
  };

  const handleSelectAll = () => {
    dispatch(selectAllItems());
  };

  const handleSearch = (event) => {
    dispatch(setSearchTerm(event.target.value));
  };

  const filteredItems = items.filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));
  const pageCount = Math.ceil(filteredItems.length / 10);

  const [currentPage, setCurrentPage] = useState(1);

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const startIndex = (currentPage - 1) * 10;
  const endIndex = startIndex + 10;

  const displayedItems = filteredItems.slice(startIndex, endIndex);

  return (
    <div>
      <input type="text" value={searchTerm} onChange={handleSearch} placeholder="Search..." />
      {loading ? (
        <div>Loading...</div>
      ) : error ? (
        <div>Error: {error.message}</div>
      ) : (
        <div>
          <table>
            <thead>
              <tr>
                <th>
                  <input type="checkbox" checked={selectedItems.length === filteredItems.length} onChange={handleSelectAll} />
                </th>
                <th>Name</th>
              </tr>
            </thead>
            <tbody>
              {displayedItems.map(item => (
                <tr key={item.id}>
                  <td>
                    <input type="checkbox" checked={selectedItems.includes(item.id)} onChange={() => handleItemSelect(item.id)} />
                  </td>
                  <td>{item.name}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div>Total selected items: {selectedItems.length}</div>
          <div>
            {Array.from({ length: pageCount }, (_, i) => i + 1).map(page => (
              <button key={page} onClick={() => handlePageChange(page)}>{page}</button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default ItemsList;
```

