def get_even_sorted(numbers):
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list of integers")

    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    even_numbers = []
    for num in numbers:
        if not isinstance(num, int):
            raise TypeError("Input list must contain only integers")
        if num % 2 == 0:
            even_numbers.append(num)
        if is_prime(num):
            raise ValueError("Input list cannot contain prime numbers")

    even_numbers.sort()
    for even_num in even_numbers:
        yield even_num
