    def __str__(self):
        return f"Vector3D({self.x}, {self.y}, {self.z})"

    def __add__(self, other):
        return Vector3D(self.x + other.x,
                        self.y + other.y,
                        self.z + other.z)

    def __mul__(self, scalar):
        return Vector3D(self.x * scalar,
                        self.y * scalar,
                        self.z * scalar)
