function convert24HourFormatTo12HourFormat(hours) {
    if (hours > 12) {
      return (hours - 12) + "PM";
    } else if (hours == 12) {
      return hours + "PM";
    } else if (hours == 0) {
        return 12 + "AM";
    } else {
      return hours + "AM";
    }   
}

def Fib_recursive(n):
    if n <= 1:
        return n
    else:
        return Fib_recursive(n - 1) + Fib_recursive(n - 2)

