## Backend - app/api/routes/bookings.py

```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from app.api.deps import get_db, get_current_user
from app.models.booking import Booking
from app.models.user import User
from app.schemas.booking import (
    BookingCreate,
    BookingUpdate,
    BookingResponse,
    BookingListResponse,
)

router = APIRouter()

@router.get("/", response_model=BookingListResponse)
async def list_bookings(
    page: int = Query(1, ge=1),
    limit: int = Query(10, ge=1, le=100),
    search: Optional[str] = None,
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Booking).filter(Booking.user_id == current_user.id)

    if search:
        query = query.filter(Booking.title.ilike(f"%{search}%"))
    if status:
        query = query.filter(Booking.status == status)

    total = query.count()
    bookings = query.offset((page - 1) * limit).limit(limit).all()

    return BookingListResponse(
        data=bookings,
        total=total,
        page=page,
        limit=limit
    )

@router.get("/{id}", response_model=BookingResponse)
async def get_booking(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    booking = db.query(Booking).filter(
        Booking.id == id,
        Booking.user_id == current_user.id
    ).first()

    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")

    return booking

@router.post("/", response_model=BookingResponse, status_code=201)
async def create_booking(
    data: BookingCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    booking = Booking(**data.model_dump(), user_id=current_user.id)
    db.add(booking)
    db.commit()
    db.refresh(booking)
    return booking

@router.put("/{id}", response_model=BookingResponse)
async def update_booking(
    id: str,
    data: BookingUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    booking = db.query(Booking).filter(
        Booking.id == id,
        Booking.user_id == current_user.id
    ).first()

    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")

    for key, value in data.model_dump(exclude_unset=True).items():
        setattr(booking, key, value)

    db.commit()
    db.refresh(booking)
    return booking

@router.delete("/{id}", status_code=204)
async def delete_booking(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    booking = db.query(Booking).filter(
        Booking.id == id,
        Booking.user_id == current_user.id
    ).first()

    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")

    db.delete(booking)
    db.commit()
```

## Frontend - src/stores/bookings.ts

```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Booking {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useBookingStore = defineStore('bookings', () => {
  const bookings = ref<Booking[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchBookings = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/bookings', { params });
      bookings.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching bookings';
    } finally {
      loading.value = false;
    }
  };

  const createBooking = async (data: Partial<Booking>) => {
    const { data: newBooking } = await api.post('/bookings', data);
    bookings.value.unshift(newBooking);
    return newBooking;
  };

  const updateBooking = async (id: string, data: Partial<Booking>) => {
    const { data: updated } = await api.put(`/bookings/${id}`, data);
    const index = bookings.value.findIndex(item => item.id === id);
    if (index !== -1) {
      bookings.value[index] = updated;
    }
    return updated;
  };

  const deleteBooking = async (id: string) => {
    await api.delete(`/bookings/${id}`);
    bookings.value = bookings.value.filter(item => item.id !== id);
  };

  return {
    bookings,
    loading,
    error,
    pagination,
    fetchBookings,
    createBooking,
    updateBooking,
    deleteBooking,
  };
});
```

